window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[89]={"id":"089","numero":89,"titre":"Altération fonction auditive","objectifs":[{"id":"89-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un test auditif tonal","contenu":"<p>Le <strong>test auditif tonal</strong> est <span class=\"kw-def\">l'examen mesurant le seuil de perception d'un sujet à des sons purs</span> d'intensité (en dB) et de fréquence (en Hz) variables, par <span class=\"kw-def\">conduction aérienne (CA)</span> et <span class=\"kw-def\">conduction osseuse (CO)</span> séparément, dans le but de quantifier objectivement une perte auditive et d'en préciser le mécanisme (transmission / perception / mixte).</p>\n\n      <table >\n        <thead>\n          <tr><th>Notion</th><th>Définition</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Surdité</strong></td>\n            <td><span class=\"kw-def\">Symptôme</span> défini par une baisse de l'audition, quelle que soit son importance, quelle que soit son étiologie. <br><strong>Signes d'appel :</strong> baisse de l'<span class=\"kw-clinique\">audibilité</span> (« je n'entends pas ») ou baisse de l'<span class=\"kw-clinique\">intelligibilité</span> (« je ne comprends pas »).</td>\n          </tr>\n          <tr>\n            <td><strong>Hypoacousie</strong></td>\n            <td>Synonyme de surdité, souvent employé pour <span class=\"kw-clinique\">les</span> surdités <span class=\"kw-def\">légères ou moyennes</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Cophose</strong></td>\n            <td><span class=\"kw-def\">Surdité totale</span>, uni- ou bilatérale (PAM ≥ <span class=\"kw-chiffre\">120 dB</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Son</strong></td>\n            <td>Vibration sonore caractérisée par : <br><strong>Intensité</strong> en décibels (dB) ; champ auditif humain <span class=\"kw-chiffre\">0-120 dB</span>. <br><strong>Fréquence</strong> en Hertz (Hz) ; champ auditif humain <span class=\"kw-chiffre\">20-20 000 Hz</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Gammes de fréquence</strong></td>\n            <td><strong>Graves :</strong> <span class=\"kw-chiffre\">20-500 Hz</span>. <br><strong>Médiums :</strong> <span class=\"kw-chiffre\">500-2 000 Hz</span> (oreille très sensible à 30-80 dB). <br><strong>Aigus :</strong> <span class=\"kw-chiffre\">2 000-20 000 Hz</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Conduction aérienne (CA)</strong></td>\n            <td>Pavillon → conduit auditif externe → tympan → osselets → cochlée.</td>\n          </tr>\n          <tr>\n            <td><strong>Conduction osseuse (CO)</strong></td>\n            <td>Vibration directe au niveau de la <span class=\"kw-def\">mastoïde</span> transmise à la cochlée (court-circuite l'oreille externe et l'oreille moyenne).</td>\n          </tr>\n          <tr>\n            <td><strong>Audiométrie tonale <span class=\"kw-bio\">vs</span> vocale</strong></td>\n            <td>Audiométrie <strong>tonale</strong> = sons purs / seuil. <br>Audiométrie <strong>vocale</strong> = sons signifiants (mots) / intelligibilité.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le test auditif tonal donne objectivement la <span class=\"kw-def\">PAM</span> (perte audiométrique moyenne) sur <span class=\"kw-clinique\">les</span> fréquences conversationnelles <span class=\"kw-chiffre\">500 / 1 000 / 2 000 / 4 000 Hz</span> en CA — base de la <span class=\"kw-def\">classification</span> de sévérité (cf <em>obj-1</em>).\n      </div>","frequence":0},{"id":"89-2","rang":"A","rubrique":"Définition","titre":"Connaître les grands types de surdité","contenu":"<p>Deux classifications à connaître : <strong>selon le mécanisme</strong> (transmission, perception, mixte, cophose) et <strong>selon la sévérité</strong> (PAM en dB).</p>\n\n      <h4>1 · <span class=\"kw-def\">Classification</span> selon le mécanisme</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Atteinte</th><th>Acoumétrie / Audiogramme</th><th>Particularités cliniques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Surdité de transmission (ST)</strong></td>\n            <td><span class=\"kw-def\">Oreille externe</span> (CAE) ou <span class=\"kw-def\">moyenne</span> (tympan, osselets, fenêtre ovale)</td>\n            <td><span class=\"kw-bio\">CO normale</span> (0-20 dB) <br><span class=\"kw-bio\">CA abaissée</span> (gap aéro-osseux) <br><span class=\"kw-clinique\">Weber sourd</span> · <span class=\"kw-clinique\">Rinne négatif</span></td>\n            <td><span class=\"kw-clinique\">Jamais totale</span> (max ~<span class=\"kw-chiffre\">60 dB</span>) <br>Pas de modification de la voix (autophonie possible) <br><span class=\"kw-clinique\">Paracousie</span> (mieux dans le bruit / au téléphone) <br>Acouphènes graves, peu gênants</td>\n          </tr>\n          <tr>\n            <td><strong>Surdité de perception (SP) / neurosensorielle</strong></td>\n            <td><span class=\"kw-def\">Endocochléaire</span> (cochlée) ou <span class=\"kw-def\">rétrocochléaire</span> (VIII, voies centrales)</td>\n            <td><span class=\"kw-bio\">CO et CA superposées et abaissées</span> (pas de gap) <br>Perte prédominant sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">aigus</span> <br><span class=\"kw-clinique\">Weber sain</span> · <span class=\"kw-clinique\">Rinne positif</span></td>\n            <td>Intensité variable jusqu'à <span class=\"kw-alerte\">cophose</span> <br>Élévation de la voix si bilatérale sévère <br><span class=\"kw-clinique\">Signe du « cocktail party »</span> (aggravée dans le bruit) <br>Acouphènes aigus, mal tolérés <br>Distorsions sonores possibles (recrutement, diplacousie)</td>\n          </tr>\n          <tr>\n            <td><strong>Surdité mixte</strong></td>\n            <td>Association d'une ST + SP</td>\n            <td>CO abaissée <strong>+</strong> gap aéro-osseux maintenu (CA plus touchée que CO)</td>\n            <td>Sémiologie composite — ex. otospongiose évoluée, otite chronique compliquée</td>\n          </tr>\n          <tr>\n            <td><strong>Cophose</strong></td>\n            <td>Forme extrême (SP le plus souvent)</td>\n            <td>PAM ≥ <span class=\"kw-chiffre\">120 dB</span></td>\n            <td><span class=\"kw-alerte\">Surdité totale</span>, uni- ou bilatérale</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · <span class=\"kw-def\">Classification</span> selon la sévérité (PAM moyenne sur 500/1 000/2 000/4 000 Hz, en CA)</h4>\n      <table >\n        <thead>\n          <tr><th>Niveau</th><th>PAM</th><th>Repère sonore</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Audition normale</strong></td><td><span class=\"kw-chiffre\">0-20 dB</span></td><td>—</td></tr>\n          <tr><td><strong>Légère</strong></td><td><span class=\"kw-chiffre\">21-40 dB</span></td><td>Chuchotement (35 dB)</td></tr>\n          <tr><td><strong>Moyenne</strong></td><td><span class=\"kw-chiffre\">41-70 dB</span></td><td>Conversation tranquille (60 dB)</td></tr>\n          <tr><td><strong>Sévère</strong></td><td><span class=\"kw-chiffre\">71-90 dB</span></td><td>Aspirateur (70 dB)</td></tr>\n          <tr><td><strong>Profonde</strong></td><td><span class=\"kw-chiffre\">≥ 90 dB</span></td><td>Moto (90 dB)</td></tr>\n          <tr><td><strong>Totale (cophose)</strong></td><td><span class=\"kw-chiffre\">≥ 120 dB</span></td><td>Discothèque (110 dB)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau.</strong> Une <span class=\"kw-alerte\">ST n'est jamais totale</span> (max ~60 dB). Toute surdité unilatérale profonde ou totale impose d'éliminer une SP rétrocochléaire (<span class=\"kw-alerte\">neurinome de l'acoustique</span>) par <span class=\"kw-imagerie\">IRM</span> injectée.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 150 — Otite · 103 — <span class=\"kw-clinique\">Vertige</span></em></p>","frequence":1},{"id":"89-3","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les critères des tests acoumétriques","contenu":"<p>L'<span class=\"kw-def\">acoumétrie au diapason</span> est une technique clinique <strong>rapide, simple, sans équipement sophistiqué</strong> qui différencie une ST d'une SP en consultation. Deux épreuves complémentaires : <strong>Weber</strong> (compare la CO entre <span class=\"kw-clinique\">les</span> 2 oreilles) et <strong>Rinne</strong> (compare CA et CO d'une même oreille).</p>\n\n      <h4>1 · Épreuve de Weber</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Principe</strong></td><td>Diapason en vibration posé <span class=\"kw-def\">au centre du crâne</span> (front ou vertex), équidistant des 2 oreilles. Teste <span class=\"kw-clinique\">les</span> 2 oreilles <strong>simultanément</strong>. Compare la <span class=\"kw-def\">CO</span> entre les 2 côtés.</td></tr>\n          <tr><td><strong>Résultat normal</strong></td><td>Son entendu <span class=\"kw-bio\">de façon égale dans les 2 oreilles ou diffus</span> → <strong>Weber indifférent</strong>.</td></tr>\n          <tr><td><strong>ST</strong></td><td>Weber latéralisé vers l'oreille <span class=\"kw-clinique\">sourde</span> (si unilatérale) ou la plus sourde (si bilatérale).</td></tr>\n          <tr><td><strong>SP</strong></td><td>Weber latéralisé vers l'oreille <span class=\"kw-clinique\">saine</span> (si unilatérale) ou la moins sourde (si bilatérale).</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Épreuve de Rinne</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Principe</strong></td><td>Teste chaque oreille <strong>séparément</strong> (mémo : Rinne = Inverser). <br>1. Diapason en vibration posé sur la <span class=\"kw-def\">mastoïde</span> (CO). <br>2. Dès que le patient ne perçoit plus le son en CO, déplacer le diapason devant le <span class=\"kw-def\">pavillon</span> (CA). <br>3. Calcul <strong>Rinne = CA − CO</strong>.</td></tr>\n          <tr><td><strong>Résultat normal</strong></td><td>Le patient continue à percevoir le son <span class=\"kw-bio\">plus longtemps par CA que par CO</span> → <strong>Rinne acoumétrique positif</strong> (CA − CO &gt; 0).</td></tr>\n          <tr><td><strong>ST</strong></td><td><span class=\"kw-bio\">Rinne acoumétrique négatif ou nul</span> (CA − CO <span class=\"kw-chiffre\">≤ 0</span>) — la CO devient meilleure que la CA car l'obstacle dans l'oreille externe/moyenne abolit la transmission aérienne mais la cochlée reste fonctionnelle.</td></tr>\n          <tr><td><strong>SP</strong></td><td>Rinne acoumétrique <span class=\"kw-bio\">positif</span> (CA − CO &gt; 0) — comme à l'état normal, mais <span class=\"kw-clinique\">les</span> 2 voies sont abaissées (cochlée atteinte).</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Synthèse clinique</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Weber</th><th>Rinne acoumétrique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Audition normale</strong></td><td>Centré (indifférent)</td><td>Positif (CA &gt; CO)</td></tr>\n          <tr><td><strong>Surdité de transmission</strong></td><td>Latéralisé vers le côté <span class=\"kw-clinique\">sourd</span></td><td><span class=\"kw-bio\">Négatif</span> (CO &gt; CA)</td></tr>\n          <tr><td><strong>Surdité de perception</strong></td><td>Latéralisé vers le côté <span class=\"kw-clinique\">sain</span></td><td>Positif (CA &gt; CO)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pratique.</strong> L'acoumétrie est l'outil d'orientation au lit du patient en consultation ORL, médecine générale ou neurologie. Anormale → audiométrie tonale + vocale en <span class=\"kw-bio\">complément</span>. <span class=\"kw-clinique\">Une acoumétrie normale n'élimine pas une surdité légère</span> — c'est un test grossier.\n      </div>","frequence":2},{"id":"89-4","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes de réalisation d’une audiométrie tonale, vocale","contenu":"<p>Deux examens <strong>subjectifs</strong> complémentaires, demandant la coopération du patient. Toujours couplés en pratique.</p>\n\n      <h4>1 · Audiométrie tonale liminaire</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Principe</strong></td><td><span class=\"kw-def\">Examen subjectif</span> testant chaque oreille <strong>séparément</strong> par stimulation sonore avec des <span class=\"kw-def\">sons purs</span> d'intensités et de fréquences variées (<span class=\"kw-chiffre\">125-8 000 Hz</span>). <br><strong>CA</strong> = casque sur l'oreille. <br><strong>CO</strong> = vibrateur mastoïdien.</td></tr>\n          <tr><td><strong>Objectif</strong></td><td>Déterminer le <span class=\"kw-def\">seuil subjectif liminaire d'audition</span> pour chaque voie (CA et CO) et chaque fréquence.</td></tr>\n          <tr><td><strong>Représentation</strong></td><td>Axe horizontal = fréquences (250-8 000 Hz). <br>Axe vertical = seuil en dB (vers le bas = perte croissante). <br>Courbe CA + courbe CO superposées sur l'audiogramme.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Profils audiométriques (4 types)</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Conduction osseuse</th><th>Conduction aérienne</th><th>Gap aéro-osseux</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Audition normale</strong></td><td><span class=\"kw-bio\">0-20 dB</span></td><td><span class=\"kw-bio\">0-20 dB</span></td><td>❌ Non (courbes superposées)</td></tr>\n          <tr><td><strong>Surdité de transmission</strong></td><td><span class=\"kw-bio\">Normale (0-20 dB)</span></td><td><span class=\"kw-bio\">Abaissée &gt; 20 dB</span></td><td>✅ <strong>Oui</strong></td></tr>\n          <tr><td><strong>Surdité de perception</strong></td><td><span class=\"kw-bio\">Abaissée &gt; 20 dB</span></td><td><span class=\"kw-bio\">Abaissée &gt; 20 dB</span> (superposée à la CO)</td><td>❌ Non · perte prédominant sur <span class=\"kw-clinique\">les</span> aigus (sauf <span class=\"kw-clinique\">Ménière</span>)</td></tr>\n          <tr><td><strong>Surdité mixte</strong></td><td>Abaissée &gt; 20 dB</td><td>Abaissée &gt; 20 dB (CA plus touchée que CO)</td><td>✅ <strong>Oui</strong> (CA &lt; CO)</td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/audiogramme-types-de-surdite-tonal.png\" alt=\"Audiogramme tonal : 4 profils superposés (normal, ST avec gap aéro-osseux, SP avec courbes superposées sur les aigus, mixte).\" loading=\"lazy\">\n        <figcaption>Audiogramme tonal — <span class=\"kw-clinique\">les</span> 4 profils caractéristiques de l'audition (normale, ST, SP, mixte). Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <h4>3 · Audiométrie vocale</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Principe</strong></td><td><span class=\"kw-def\">Examen subjectif</span> d'évaluation de l'<span class=\"kw-def\">intelligibilité</span>. Stimulation par <strong>sons complexes</strong> : mots monosyllabiques/bisyllabiques signifiants, logatomes (voyelle-consonne-voyelle) non signifiants, ± adjonction de bruit perturbant. <br>Testing soit en <strong>champ libre</strong> (2 oreilles simultanées) soit à chaque oreille séparément au casque.</td></tr>\n          <tr><td><strong>Recueil</strong></td><td>Pourcentage de reconnaissance des mots d'une liste en fonction de l'<span class=\"kw-def\">intensité du signal sonore</span>.</td></tr>\n          <tr><td><strong>Paramètres clés</strong></td><td><strong>Seuil d'intelligibilité</strong> = intensité à laquelle <span class=\"kw-chiffre\">50 %</span> des items sont compris et répétés. <br><strong>Maximum d'intelligibilité</strong> = pourcentage maximal d'items compris à une intensité donnée. <br>Audition normale :<span class=\"kw-chiffre\"> 100 %</span> atteint dès <span class=\"kw-chiffre\">30 dB</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Discrimination endo- <span class=\"kw-bio\">vs</span> rétrocochléaire en SP</h4>\n      <table >\n        <thead>\n          <tr><th>Type de surdité</th><th><span class=\"kw-def\">Score</span> maximal d'intelligibilité</th><th>Effet de ↑ volume</th><th>Roll-over</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Endocochléaire</strong> (presbyacousie, Ménière, ototoxicité)</td><td><span class=\"kw-bio\">Conservé &gt; 70-80 %</span></td><td>Augmente l'intelligibilité (recrutement)</td><td>Non</td></tr>\n          <tr><td><strong>Rétrocochléaire</strong> (neurinome, tronc cérébral)</td><td><span class=\"kw-bio\">Réduit &lt; 60 %</span></td><td><span class=\"kw-alerte\">Diminue</span> l'intelligibilité à forte intensité</td><td><span class=\"kw-alerte\">Oui</span></td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/audiogramme-vocal-intelligibilite.png\" alt=\"Audiogramme vocal : courbes A normale, B perte modérée, C perte sévère ; seuil d'intelligibilité à 20 dB, maximum à 30 dB pour A.\" loading=\"lazy\">\n        <figcaption>Audiogramme vocal — courbes A/B/C montrant le pourcentage d'intelligibilité en fonction de l'intensité (seuil à 20 dB, maximum à 30 dB pour une audition normale). Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau rétrocochléaire.</strong> Une <span class=\"kw-alerte\">discordance entre audiométrie tonale (perte modérée) et audiométrie vocale (score max effondré, roll-over)</span> impose une <span class=\"kw-imagerie\">IRM</span> cérébrale + APC injectée pour éliminer un neurinome de l'acoustique.\n      </div>","frequence":2},{"id":"89-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes de l’impédancemétrie","contenu":"<p>L'<span class=\"kw-def\">impédancemétrie</span> mesure l'impédance du tympan et de la chaîne ossiculaire et ses modifications sous l'effet de variations de pression (surpression/<span class=\"kw-def\">dépression</span>) dans le CAE. <strong>Examen objectif</strong> — ne demande pas la coopération du patient (utilisable chez l'enfant, le sujet non coopérant).</p>\n\n      <h4>1 · Conditions et objectifs</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Objectif</strong></td><td>Fournir de façon <span class=\"kw-def\">objective</span> des renseignements sur la valeur fonctionnelle de la <strong>trompe d'Eustache</strong> et du <strong>système tympano-ossiculaire</strong>.</td></tr>\n          <tr><td><strong>Condition</strong></td><td><span class=\"kw-ci\">Tympan fermé (sans perforation)</span> — sinon impédancemétrie ininterprétable. Otoscopie systématique avant.</td></tr>\n          <tr><td><strong>Composantes</strong></td><td><strong>Tympanométrie</strong> (courbe pression-compliance) <strong>+</strong> <strong>réflexe stapédien</strong>.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Tympanométrie — 4 profils</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Courbe</th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Type A (normal)</strong></td><td><span class=\"kw-bio\">Pic centré sur 0 mm H₂O</span>, compliance normale, en « toit de pagode »</td><td>Oreille moyenne <span class=\"kw-clinique\">normale</span></td></tr>\n          <tr><td><strong>Type B (plat)</strong></td><td><span class=\"kw-bio\">Absence de pic</span>, tympan immobile, compliance nulle</td><td><span class=\"kw-clinique\">Épanchement liquidien</span> (OSM, OMA), perforation tympanique, bouchon de cérumen</td></tr>\n          <tr><td><strong>Type C</strong></td><td><span class=\"kw-bio\">Pic décalé vers les pressions négatives</span> (&lt; -100 mm H₂O)</td><td><span class=\"kw-clinique\">Dysfonction tubaire</span> (trompe d'Eustache) — précède une OSM, barotraumatisme, catarrhe tubaire</td></tr>\n          <tr><td><strong>« Tour Eiffel »</strong></td><td><span class=\"kw-bio\">Pic ample et pointu</span> centré sur 0, compliance exagérée</td><td><span class=\"kw-alerte\">Rupture / luxation de la chaîne ossiculaire</span> (séquelle d'otite, fracture ossiculaire)</td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/tympanogramme-types-A-B-C-tour-eiffel.png\" alt=\"Tympanogrammes : 4 profils (A normal en toit de pagode, B plat, C décalé vers pressions négatives, Tour Eiffel à pic ample).\" loading=\"lazy\">\n        <figcaption>Tympanogrammes — <span class=\"kw-clinique\">les</span> 4 profils caractéristiques (A normal, B plat = OSM/perforation, C dysfonction tubaire, Tour Eiffel = <span class=\"kw-alerte\">rupture</span> ossiculaire). Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <h4>3 · Réflexe stapédien</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Principe</strong></td><td>Stimulation auditive forte (<span class=\"kw-chiffre\">&gt; 80 dB</span>) d'un côté → <span class=\"kw-def\">contraction réflexe bilatérale du muscle stapédien</span> → rigidification de la chaîne ossiculaire → ↓ compliance mesurée dans <strong>chaque oreille</strong>.</td></tr>\n          <tr><td><strong>Seuil abaissé</strong></td><td>Surdité <span class=\"kw-bio\">endocochléaire</span> (recrutement, ex. presbyacousie).</td></tr>\n          <tr><td><strong>Réflexe aboli</strong></td><td><span class=\"kw-alerte\">Surdité rétrocochléaire</span> (neurinome) <strong>OU</strong> <span class=\"kw-alerte\">otospongiose</span> (blocage de la chaîne) <strong>OU</strong> <span class=\"kw-alerte\">paralysie faciale périphérique</span> (atteinte en amont de la branche innervant le muscle de l'étrier).</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pratique.</strong> Tympanogramme = 2ᵉ étape après l'otoscopie devant une ST. Profil B + otoscopie tympan mat ambré bombé = <span class=\"kw-clinique\">OSM</span>. Profil A + RS aboli = <span class=\"kw-clinique\">otospongiose</span>. Tour Eiffel = lyse/<span class=\"kw-alerte\">rupture</span> ossiculaire.\n      </div>","frequence":0},{"id":"89-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principes d’un test auditif objectif par potentiels évoqués auditifs (PEA)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">potentiels évoqués auditifs précoces (PEAP)</span>, dits du tronc cérébral, sont un test <strong>objectif non invasif</strong> qui enregistre les potentiels neurogènes évoqués dans les <span class=\"kw-chiffre\">10 ms</span> suivant une stimulation acoustique (électrodes de surface cutanées).</p>\n\n      <h4>1 · Principe et ondes</h4>\n      <table >\n        <thead>\n          <tr><th>Onde</th><th>Origine</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Onde I</strong></td><td><span class=\"kw-def\">Cochlée</span></td></tr>\n          <tr><td><strong>Onde II</strong></td><td><span class=\"kw-def\">Nerf auditif (VIII)</span></td></tr>\n          <tr><td><strong>Ondes III, IV, V</strong></td><td><span class=\"kw-def\">Tronc cérébral</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Intérêts</h4>\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Otologique — mesure objective du seuil</strong></td><td><span class=\"kw-chiffre\">Précision 10-15 dB dès la naissance</span>. <br>Audiométrie objective de l'<span class=\"kw-clinique\">enfant</span> ou du <span class=\"kw-clinique\">sujet non coopérant</span>. <br><span class=\"kw-imagerie\">Dépistage néonatal universel</span> de la surdité (PEAA automatisés) — voir item 47.</td></tr>\n          <tr><td><strong>Otoneurologique — topographie en SP</strong></td><td><span class=\"kw-bio\">↑ latence I-III</span> = atteinte du nerf auditif ou partie <strong>basse</strong> du tronc cérébral. <br><span class=\"kw-bio\">↑ latence III-V</span> = anomalie plus <strong>haute</strong> dans le tronc cérébral.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Limites</h4>\n      <ul>\n        <li><span class=\"kw-ci\">Pas d'étude fréquence par fréquence</span> des réponses.</li>\n        <li>Explore une <strong>plage de fréquences aiguës</strong> de l'audiométrie (pas <span class=\"kw-clinique\">les</span> graves).</li>\n        <li>La <span class=\"kw-ci\">profondeur de la surdité</span> peut gêner l'interprétation des courbes pour l'analyse des latences.</li>\n      </ul>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/pea-potentiels-evoques-auditifs.png\" alt=\"Tracé PEA : 5 ondes successives (I cochlée, II nerf auditif, III-IV-V tronc cérébral) avec leurs latences normales.\" loading=\"lazy\">\n        <figcaption>PEA — tracé des 5 ondes successives (I cochlée, II nerf VIII, III-IV-V tronc cérébral) utilisées pour le diagnostic topographique des surdités de perception. Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <h4>4 · Différence avec <span class=\"kw-clinique\">les</span> OEA (rang C — pour mémoire)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>OEA (otoémissions acoustiques)</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Principe</strong></td><td>Recueil d'un son émis par la contraction active des <span class=\"kw-def\">cellules ciliées externes (CCE)</span> en réponse à des sons brefs envoyés dans le CAE.</td></tr>\n          <tr><td><strong>Avantages</strong></td><td><span class=\"kw-clinique\">Simple, rapide (~1 min), fiable, non-invasif</span> · utilisé dans le <span class=\"kw-def\">dépistage</span> néonatal en <span class=\"kw-bio\">complément</span> des PEAA.</td></tr>\n          <tr><td><strong>Interprétation</strong></td><td>OEA présentes = système périphérique intègre (perte <span class=\"kw-chiffre\">&lt; 30 dB</span>). <br>OEA absentes = hypoacousie &gt; 30 dB possible → poursuivre l'exploration.</td></tr>\n          <tr><td><strong>Limites</strong></td><td><span class=\"kw-ci\">Ne dépistent pas les neuropathies auditives (rétrocochléaires)</span> · ne préjugent pas d'une surdité ultérieure.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ <span class=\"kw-def\">Dépistage</span> néonatal.</strong> Le <span class=\"kw-alerte\">dépistage universel de la surdité néonatale (PEAA + OEA)</span> est obl<span class=\"kw-chiffre\">iga</span>toire en France depuis 2012 (arrêté du 23/04/2012). Environ <span class=\"kw-chiffre\">1 enfant / 1 000 naissances</span> présente une surdité bilatérale néonatale, dont la majorité est d'origine <span class=\"kw-etio\">génétique</span>.\n      </div>","frequence":0},{"id":"89-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de surdités de transmission (ST)","contenu":"<p>Atteinte de l'<span class=\"kw-def\">oreille externe</span> (conduit auditif externe, CAE) ou <span class=\"kw-def\">moyenne</span> (tympan, chaîne ossiculaire, fenêtre ovale). La <span class=\"kw-clinique\">cochlée et les voies auditives sont intactes</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Caractéristiques ST</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Latéralité</strong></td><td>Peuvent être uni- ou bilatérales.</td></tr>\n          <tr><td><strong>Intensité maximale</strong></td><td><span class=\"kw-alerte\">Jamais totale ❌</span> — PAM ≤ <span class=\"kw-chiffre\">60 dB</span>.</td></tr>\n          <tr><td><strong>Voix du patient</strong></td><td>Pas de modification qualitative · voix peut résonner dans l'oreille (<span class=\"kw-clinique\">autophonie</span>) · le patient <strong>n'élève pas la voix</strong>.</td></tr>\n          <tr><td><strong>Intelligibilité</strong></td><td>Souvent <span class=\"kw-clinique\">améliorée dans le bruit (paracousie)</span> et au téléphone — discriminant clé avec SP.</td></tr>\n          <tr><td><strong>Acouphènes</strong></td><td>Timbre <span class=\"kw-clinique\">grave</span>, peu gênants, bien localisés dans l'oreille malade.</td></tr>\n          <tr><td><strong>Acoumétrie</strong></td><td><span class=\"kw-bio\">Weber latéralisé vers oreille sourde</span> · <span class=\"kw-bio\">Rinne acoumétrique négatif</span> (CO &gt; CA).</td></tr>\n          <tr><td><strong>Audiométrie tonale</strong></td><td><span class=\"kw-bio\">CO normale (0-20 dB)</span> · <span class=\"kw-bio\">CA abaissée &gt; 20 dB</span> sur toutes <span class=\"kw-clinique\">les</span> fréquences ou prédominant sur les graves · <strong>gap aéro-osseux</strong> = Rinne audiométrique négatif.</td></tr>\n          <tr><td><strong>Audiométrie vocale</strong></td><td><span class=\"kw-bio\">Pas de distorsion sonore ❌</span> — pas d'altération qualitative.</td></tr>\n          <tr><td><strong>Tympanométrie</strong></td><td>Apporte des éléments précieux (type B = OSM/perforation, C = dysfonction tubaire, Tour Eiffel = lyse ossiculaire, A + RS aboli = otospongiose) · doit être réalisée à <span class=\"kw-ci\">tympan fermé</span>.</td></tr>\n          <tr><td><strong>Pédiatrie</strong></td><td>Peut s'accompagner d'un <span class=\"kw-alerte\">retard de langage chez l'enfant</span> → <span class=\"kw-def\">dépistage</span> précoce essentiel (OSM 1ʳᵉ cause de ST de l'enfant).</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Pronostic</span></strong></td><td><span class=\"kw-ttt\">Souvent curable chirurgicalement</span> (otospongiose, ossiculoplastie post-traumatique) <strong>OU</strong> appareillable facilement (prothèse auditive efficace). <br>Ex. otospongiose opérée : <span class=\"kw-chiffre\">95 % de restitution de l'audition</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pivot clinique.</strong> Devant une ST, l'<span class=\"kw-clinique\">otoscopie</span> identifie immédiatement OMA, OSM (tympan mat ambré bombé), cholestéatome (squames blanches dans l'attique), perforation, bouchon de cérumen. <br><strong>ST + tympan normal</strong> = <span class=\"kw-clinique\">otospongiose</span> jusqu'à preuve du contraire (cf <em>obj-9</em>).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 150 — Otite</em></p>","frequence":0},{"id":"89-8","rang":"B","rubrique":"Examens complémentaires","titre":"Indication des examens d’imagerie devant une ST","contenu":"<p>L'examen de référence est la <span class=\"kw-imagerie\">TDM des rochers en fenêtre osseuse</span>, <strong>haute résolution</strong>, <strong>non injectée</strong>. L'<span class=\"kw-imagerie\">IRM</span> n'a quasiment pas de place en 1ʳᵉ intention dans la ST.</p>\n\n      <h4>Indications de la <span class=\"kw-imagerie\">TDM</span> des rochers</h4>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Question diagnostique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>ST à tympan normal</strong></td>\n            <td><span class=\"kw-imagerie\">TDM des rochers systématique</span> → recherche d'<strong>otospongiose</strong> (foyers hypodenses platinaires/labyrinthiques, épaississement de la platine), <strong>malformation ossiculaire</strong>, <strong>déhiscence du canal semi-circulaire supérieur</strong>, <strong>lyse / fracture ossiculaire</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>ST post-traumatique</strong></td>\n            <td><span class=\"kw-imagerie\">TDM des rochers</span> → <strong>fracture du rocher longitudinale</strong> (atteinte oreille moyenne, osselets), <strong>hémotympan</strong>, <strong>luxation ossiculaire</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Suspicion de cholestéatome</strong> (ST + otorrhée chronique fétide + tympan rétracté/polypode)</td>\n            <td><span class=\"kw-imagerie\">TDM des rochers</span> → <span class=\"kw-clinique\">masse</span> de l'attique / atrium, érosions ossiculaires. <br>± <span class=\"kw-imagerie\">IRM en diffusion</span> (cholestéatome = hypersignal — restriction de <span class=\"kw-imagerie\">diffusion</span>).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Bilan pré-opératoire</span> de <span class=\"kw-ttt\">chirurgie</span> stapédienne</strong></td>\n            <td><span class=\"kw-imagerie\">TDM systématique</span> pour identifier <span class=\"kw-clinique\">les</span> variations anatomiques à risque : <span class=\"kw-alerte\">déhiscence du nerf facial (2ᵉ portion)</span>, <span class=\"kw-alerte\">déhiscence de la veine jugulaire interne</span>, <span class=\"kw-alerte\">malformation bloquant la platine</span> (= CI à la stapédotomie).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Place spécifique dans l'otospongiose</h4>\n      <p>La <span class=\"kw-imagerie\">TDM</span> visualise <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">foyers otospongieux de la capsule otique</span> sous forme d'<span class=\"kw-imagerie\">hypodensité osseuse</span> ou d'<span class=\"kw-imagerie\">épaississement platinaire</span>.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau.</strong> <span class=\"kw-alerte\">Une TDM normale n'élimine PAS le diagnostic d'otospongiose</span> ❌ — le diagnostic reste clinico-audiométrique (ST progressive de l'adulte jeune, tympan normal, RS aboli, encoche de Carhart à 2 000 Hz). L'<span class=\"kw-imagerie\">IRM</span> n'est pas indiquée en 1ʳᵉ intention devant une ST — la <span class=\"kw-imagerie\">TDM</span> osseuse est suffisante et plus informative sur l'anatomie ossiculaire et platinaire.\n      </div>","frequence":0},{"id":"89-9","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’utilité de la tympanométrie dans le diagnostic des ST","contenu":"<p>La <span class=\"kw-def\">tympanométrie</span> est l'examen-clé de <strong>confirmation diagnostique et étiologique</strong> des ST car elle révèle des profils caractéristiques selon le mécanisme. C'est l'étape 2 après l'otoscopie.</p>\n\n      <table >\n        <thead>\n          <tr><th>Cause de ST</th><th>Tympanogramme</th><th>Otoscopie / contexte associé</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Otospongiose</strong></td>\n            <td><span class=\"kw-bio\">Type A normal</span> + <span class=\"kw-bio\">réflexe stapédien aboli</span> (blocage de la platine de l'étrier)</td>\n            <td><span class=\"kw-clinique\">Tympan normal</span> · adulte jeune · poussées vie génitale</td>\n          </tr>\n          <tr>\n            <td><strong>OSM (otite séromuqueuse)</strong></td>\n            <td><span class=\"kw-bio\">Type B plat</span></td>\n            <td>Tympan <span class=\"kw-clinique\">mat, ambré, bombé</span> ou rétracté · 1ʳᵉ cause de ST de l'enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Dysfonction tubaire / catarrhe tubaire</strong></td>\n            <td><span class=\"kw-bio\">Type C</span> (pic décalé vers <span class=\"kw-clinique\">les</span> pressions négatives)</td>\n            <td>Tympan rétracté · rhume, sinusite, barotraumatisme récent</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Rupture</span> / luxation ossiculaire</strong></td>\n            <td><span class=\"kw-bio\">« Tour Eiffel »</span> (pic ample et pointu)</td>\n            <td>Tympan généralement normal · ATCD traumatique ou séquelle d'otite</td>\n          </tr>\n          <tr>\n            <td><strong>Perforation tympanique / bouchon de cérumen</strong></td>\n            <td><span class=\"kw-bio\">Type B</span> ou <span class=\"kw-ci\">non interprétable</span> (impédancemétrie impossible si perforation)</td>\n            <td>Tympan perforé visible en otoscopie · CAE obturé</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Apport du réflexe stapédien</h4>\n      <ul>\n        <li><span class=\"kw-bio\">Aboli</span> dans l'<span class=\"kw-clinique\">otospongiose</span> (blocage de la chaîne) → drapeau majeur.</li>\n        <li><span class=\"kw-bio\">Aboli</span> dans la <span class=\"kw-alerte\">paralysie faciale périphérique</span> (atteinte en amont de la branche du muscle de l'étrier).</li>\n        <li><span class=\"kw-bio\">Aboli</span> dans la <span class=\"kw-alerte\">surdité rétrocochléaire</span> (neurinome de l'acoustique).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ <span class=\"kw-ci\">CI absolue</span>.</strong> <span class=\"kw-ci\">Perforation tympanique</span> → tympanométrie ininterprétable. <strong>Otoscopie obl<span class=\"kw-chiffre\">iga</span>toire avant</strong> toute impédancemétrie.\n      </div>","frequence":0},{"id":"89-10","rang":"A","rubrique":"Etiologie","titre":"Connaître les étiologies principales des ST","contenu":"<p>Trois grands cadres : <strong>ST à tympan normal</strong> (otospongiose +++), <strong>ST par atteinte tympanique / OM</strong> (otites, séquelles, bouchon, cholestéatome), <strong>ST traumatique</strong>.</p>\n\n      <h4>1 · ST à tympan normal</h4>\n      <table >\n        <thead>\n          <tr><th></th><th><span class=\"kw-etio\">Acquise</span></th><th><span class=\"kw-etio\">Congénitale</span></th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Stable</strong></td>\n            <td><span class=\"kw-etio\">Lyse ossiculaire</span> <br><span class=\"kw-etio\">Fracture ossiculaire</span></td>\n            <td><span class=\"kw-etio\">Aplasie de l'oreille</span> (origine <span class=\"kw-etio\">génétique</span> ou embryopathie rubéolique/<span class=\"kw-etio\">toxique</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Évolutive</strong></td>\n            <td><span class=\"kw-etio\">Otospongiose ⭐⭐⭐</span> — cf focus ci-dessous</td>\n            <td><span class=\"kw-etio\">Maladie de Lobstein</span> (ostéogenèse imparfaite)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · ST par atteinte tympanique / oreille moyenne (otoscopie anormale)</h4>\n      <table >\n        <thead>\n          <tr><th>Cause</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Otites externes, OMA</strong></td>\n            <td><span class=\"kw-etio\">ST contingente</span>, guérit le plus souvent avec l'épisode <span class=\"kw-etio\">infectieux</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>OSM à tympan fermé</strong></td>\n            <td><span class=\"kw-etio\">1ʳᵉ cause de ST de l'enfant</span>. Traitement par <span class=\"kw-ttt\">aérateur trans-tympanique (ATT)</span> si persistance/répétition.</td>\n          </tr>\n          <tr>\n            <td><strong>Otites chroniques</strong></td>\n            <td>Cholestéatomateuse (<span class=\"kw-alerte\">ostéolyse extensive, risque de complication intracrânienne</span>) ou non cholestéatomateuse. La ST peut être <span class=\"kw-clinique\">le seul signe révélateur</span> d'un cholestéatome.</td>\n          </tr>\n          <tr>\n            <td><strong>Séquelles d'otite</strong></td>\n            <td><strong>Perforation</strong> tympanique <br>Tympan <strong>flaccide</strong> ou <strong>atélectasie</strong> (accolé au fond de caisse) <br><strong>Lyse</strong> ossiculaire avec interruption de chaîne, <strong>blocage</strong> ossiculaire cicatriciel (<span class=\"kw-etio\">tympanosclérose</span>) <br><strong>Dysperméabilité</strong> de la trompe d'Eustache</td>\n          </tr>\n          <tr>\n            <td><strong>Bouchon de cérumen</strong></td>\n            <td>ST survenue après un bain ± <span class=\"kw-clinique\">otalgie</span>. Diagnostic facile à l'examen. <span class=\"kw-ttt\">Traitement = extraction par lavage</span> (si tympan fermé) ou <strong>aspiration</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Tumeurs (rares)</strong></td>\n            <td><span class=\"kw-etio\">Tumeur du glomus tympanojugulaire</span> (<span class=\"kw-clinique\">masse</span> rétrotympanique pulsatile bleutée + acouphène pulsatile + <span class=\"kw-clinique\">paralysie faciale</span>) · <span class=\"kw-etio\">Carcinomes du CAE et de l'oreille moyenne</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3 · ST traumatiques</h4>\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Réversible</th><th>Permanente</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Fracture du rocher longitudinale</strong></td>\n            <td><span class=\"kw-clinique\">Simple hémotympan</span> (régressif spontanément)</td>\n            <td>Atteinte tympano-ossiculaire : <span class=\"kw-alerte\">perforation tympanique</span>, <span class=\"kw-alerte\">fracture / luxation ossiculaire</span> → réparation par <span class=\"kw-ttt\">tympanoplastie ± ossiculoplastie à distance du traumatisme</span></td>\n          </tr>\n          <tr>\n            <td><strong>Barotraumatisme</strong></td>\n            <td>Otite séreuse, hémotympan (régressifs)</td>\n            <td><span class=\"kw-alerte\">Rupture</span> tympanique persistante</td>\n          </tr>\n          <tr>\n            <td><strong>Traumatismes pénétrants par le CAE</strong></td>\n            <td>—</td>\n            <td>Luxations ossiculaires, perforations (coton-t<span class=\"kw-chiffre\">ige</span>, agents vulnérants)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Focus Otospongiose ⭐⭐⭐</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"kw-def\">Ostéodystrophie de la capsule labyrinthique</span>, origine multifactorielle (<span class=\"kw-etio\">génétique</span>, hormonale, <span class=\"kw-etio\">virale</span>…) → fixation anormale de la platine de l'étrier dans la fenêtre ovale.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td>Histologique <span class=\"kw-chiffre\">8 %</span> des sujets caucasiens · clinique <span class=\"kw-chiffre\">1 / 1 000</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Adulte jeune sans passé otologique · prédominance féminine <span class=\"kw-chiffre\">2 F / 1 H</span> · ATCD familiaux dans <span class=\"kw-chiffre\">50 %</span> des cas.</td></tr>\n          <tr><td><strong>Surdité</strong></td><td>Bilatérale, <span class=\"kw-clinique\">asymétrique dans 3/4</span> des cas · poussées lors des <span class=\"kw-clinique\">épisodes de vie génitale de la femme</span> (puberté, <span class=\"kw-ci\">grossesse</span>, allaitement, ménopause) · <span class=\"kw-bio\">ST pure → puis mixte</span> · jamais totale.</td></tr>\n          <tr><td><strong>Otoscopie</strong></td><td><span class=\"kw-clinique\">Tympan normal</span>.</td></tr>\n          <tr><td><strong>Tympanogramme</strong></td><td><span class=\"kw-bio\">Normal (type A)</span>.</td></tr>\n          <tr><td><strong>Réflexe stapédien</strong></td><td><span class=\"kw-bio\">Aboli</span> (ankylose complète) · effet « on-off » quasi pathognomonique en début d'ankylose stapédo-vestibulaire (2 déflexions négatives successives).</td></tr>\n          <tr><td><strong>Audiogramme</strong></td><td>ST + <span class=\"kw-imagerie\">encoche de Carhart à 2 000 Hz</span> caractéristique (à ne PAS confondre avec l'encoche du trauma sonore à 4 000 Hz).</td></tr>\n          <tr><td><strong>Confirmation imagerie</strong></td><td><span class=\"kw-imagerie\">TDM rochers</span> (foyers d'hypodensité, épaississement platinaire) · <span class=\"kw-alerte\">TDM normale n'élimine pas le diagnostic ❌</span>.</td></tr>\n          <tr><td><strong>Traitement</strong></td><td><span class=\"kw-ttt\">Stapédectomie ou stapédotomie</span> + prothèse stapédienne · résultats <span class=\"kw-chiffre\">excellents (95 % de restitution)</span> · alternative = prothèse auditive amplificatrice (ne stoppe pas l'<span class=\"kw-clinique\">évolution</span>).</td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/audiogramme-otospongiose-carhart.png\" alt=\"Audiogramme otospongiose : ST avec encoche de Carhart caractéristique à 2 000 Hz.\" loading=\"lazy\">\n        <figcaption>Audiogramme otospongiose — surdité de transmission avec encoche de Carhart caractéristique à 2 000 Hz (à ne PAS confondre avec l'encoche du trauma sonore à 4 000 Hz). Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/tdm-rocher-otospongiose.png\" alt=\"TDM des rochers en fenêtre osseuse : foyer otospongieux visible sous forme d'hypodensité osseuse et d'épaississement platinaire.\" loading=\"lazy\">\n        <figcaption><span class=\"kw-imagerie\">TDM</span> des rochers — foyer otospongieux (hypodensité osseuse et épaississement platinaire). Rappel : <strong><span class=\"kw-imagerie\">TDM</span> normale n'élimine pas le diagnostic</strong>. Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/fracture-rocher-longitudinale-transversale.png\" alt=\"Schéma des 2 orientations de fracture du rocher : longitudinale (oreille moyenne → ST) vs transversale (cochlée → SP).\" loading=\"lazy\">\n        <figcaption>Fracture du rocher — orientation <strong>longitudinale</strong> (atteinte des osselets → ST) <span class=\"kw-bio\">vs</span> <strong>transversale</strong> (atteinte de la cochlée → SP). Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Piège classique.</strong> <span class=\"kw-alerte\">Ne JAMAIS confondre l'encoche de Carhart (2 000 Hz, otospongiose) avec l'encoche du traumatisme sonore (4 000 Hz)</span> — piège d'examen rédigé volontairement pour piéger <span class=\"kw-clinique\">les</span> candidats. La 1ʳᵉ est une ST chez l'adulte jeune, la 2ᵈᵉ est une SP bilatérale d'origine professionnelle.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 150 — Otite</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/external-auditory-canal-atresia","label":"Radiopaedia : External auditory canal atresia"},{"href":"https://radiopaedia.org/articles/otospongiosis-1","label":"Radiopaedia : Otospongiosis"}]},{"id":"89-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les caractéristiques de surdités de perception (SP)","contenu":"<p>Atteinte de l'<span class=\"kw-def\">endocochlée</span> (cellules ciliées de l'organe de Corti) ou des voies <span class=\"kw-def\">rétrocochléaires</span> (VIII, voies auditives centrales). La cochlée et/ou <span class=\"kw-clinique\">les</span> voies nerveuses sont lésées.</p>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Caractéristiques SP</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Latéralité</strong></td><td>Uni- ou bilatérales.</td></tr>\n          <tr><td><strong>Intensité maximale</strong></td><td>Variable, peut aller jusqu'à <span class=\"kw-alerte\">cophose</span> (totale possible).</td></tr>\n          <tr><td><strong>Voix du patient</strong></td><td><span class=\"kw-clinique\">Élévation de la voix</span> si bilatérale et sévère (« crier comme un sourd »).</td></tr>\n          <tr><td><strong>Intelligibilité</strong></td><td>Souvent <span class=\"kw-clinique\">aggravée dans le bruit</span> = <strong>signe du « cocktail party »</strong>.</td></tr>\n          <tr><td><strong>Acouphènes</strong></td><td>Timbre <span class=\"kw-clinique\">aigu</span> (<span class=\"kw-clinique\">sifflements</span>), <span class=\"kw-clinique\">mal tolérés</span>, ± bien localisés dans l'oreille.</td></tr>\n          <tr><td><strong>Signes associés possibles</strong></td><td><span class=\"kw-clinique\">Vertiges</span>, troubles de l'équilibre (atteinte labyrinthique ou nerveuse).</td></tr>\n          <tr><td><strong>Distorsions sonores</strong></td><td><span class=\"kw-clinique\">Diplacousie</span> (perception différente de la hauteur), <span class=\"kw-clinique\">recrutement</span> (perception douloureuse des sons forts — endocochléaire), modification du timbre.</td></tr>\n          <tr><td><strong>Acoumétrie</strong></td><td><span class=\"kw-bio\">Weber latéralisé vers oreille saine</span> · <span class=\"kw-bio\">Rinne acoumétrique positif</span>.</td></tr>\n          <tr><td><strong>Audiométrie tonale</strong></td><td><span class=\"kw-bio\">Courbes CO et CA superposées et abaissées</span> (&gt; 20 dB) · perte prédominant sur <span class=\"kw-clinique\">les</span> <strong>fréquences aiguës</strong>. <br>Exception : <span class=\"kw-clinique\">maladie de Ménière</span> = SP qui peut prédominer sur toutes les fréquences ou sur les <strong>graves</strong>.</td></tr>\n          <tr><td><strong>Audiométrie vocale</strong></td><td><span class=\"kw-bio\">Distorsions sonores possibles</span> (recrutement, diplacousie) · différencie endo- (<span class=\"kw-def\">score</span> conservé &gt;<span class=\"kw-chiffre\"> 70-80 %</span>) <span class=\"kw-bio\">vs</span> rétrocochléaire (score &lt;<span class=\"kw-chiffre\"> 60 %</span>, <strong>roll-over</strong>).</td></tr>\n          <tr><td><strong>Tympanométrie</strong></td><td>Normale (tympan + chaîne ossiculaire intacts).</td></tr>\n          <tr><td><strong>Réflexe stapédien</strong></td><td><span class=\"kw-bio\">Seuil abaissé</span> si atteinte endocochléaire (recrutement) · <span class=\"kw-bio\">aboli</span> si atteinte rétrocochléaire.</td></tr>\n          <tr><td><strong>PEAP</strong></td><td><span class=\"kw-bio\">Diminution du seuil auditif</span> · diagnostic topographique grâce aux latences (↑ I-III = nerf VIII, ↑ III-V = tronc cérébral).</td></tr>\n          <tr><td><strong>OEA</strong></td><td><span class=\"kw-bio\">Anormales si endocochléaire</span> · normales si rétrocochléaire.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Distinguer endocochléaire <span class=\"kw-bio\">vs</span> rétrocochléaire — principe du recrutement</h4>\n      <table >\n        <thead>\n          <tr><th>Type de SP</th><th>Recrutement</th><th>Effet ↑ volume sur l'intelligibilité</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Endocochléaire</strong> (atteinte cochlée)</td><td>✅ Présent (cellules sensorielles résiduelles recrutables)</td><td>Forte amélioration (<span class=\"kw-def\">score</span> &gt;<span class=\"kw-chiffre\"> 70 %</span>)</td></tr>\n          <tr><td><strong>Rétrocochléaire</strong> (atteinte nerveuse)</td><td>❌ Absent (atteinte de la transmission nerveuse)</td><td>Peu ou pas d'amélioration · <span class=\"kw-alerte\">roll-over possible</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau majeur.</strong> Toute <span class=\"kw-alerte\">SP unilatérale</span> ou <span class=\"kw-alerte\">bilatérale asymétrique</span> impose une <span class=\"kw-imagerie\">IRM cérébrale + APC injectée</span> pour éliminer un <strong>neurinome de l'acoustique</strong> (<span class=\"kw-chiffre\">10 %</span> des surdités unilatérales brusques). Pas de diagnostic « idiopathique » avant <span class=\"kw-imagerie\">IRM</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 103 — <span class=\"kw-clinique\">Vertige</span></em></p>","frequence":0},{"id":"89-12","rang":"A","rubrique":"Examens complémentaires","titre":"Indication des examens d’imagerie devant une SP","contenu":"<p>L'examen de référence en SP de l'adulte est l'<span class=\"kw-imagerie\">IRM cérébrale + angles ponto-cérébelleux (APC), injectée au gadolinium</span>, avec des séquences <strong>T1 + T2 haute résolution</strong> (FIESTA / CISS) sur l'oreille interne. La <span class=\"kw-imagerie\">TDM</span> est limitée à des indications spécifiques.</p>\n\n      <h4>1 · Indications de l'<span class=\"kw-imagerie\">IRM</span></h4>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Question diagnostique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>SP unilatérale</strong></td>\n            <td><span class=\"kw-imagerie\">IRM systématique</span> → <span class=\"kw-alerte\">éliminer un neurinome de l'acoustique (schwannome vestibulaire)</span> retrouvé dans <span class=\"kw-chiffre\">~10 %</span> des cas.</td>\n          </tr>\n          <tr>\n            <td><strong>Surdité brusque (SUB) « coup de tonnerre dans un ciel serein »</strong></td>\n            <td><span class=\"kw-imagerie\">IRM systématique</span> (en <span class=\"kw-alerte\">urgence</span> si possible, différée sinon) →<span class=\"kw-chiffre\"> 10 %</span> des SUB révèlent un neurinome · le reste = <span class=\"kw-etio\">virale</span>, vasculaire, idiopathique.</td>\n          </tr>\n          <tr>\n            <td><strong>SP asymétrique ou rapidement évolutive</strong></td>\n            <td><span class=\"kw-imagerie\">IRM</span> · drapeau majeur pour atteinte <strong>rétrocochléaire</strong> (neurinome, méningiome de l'APC).</td>\n          </tr>\n          <tr>\n            <td><strong>SP + acouphènes unilatéraux + <span class=\"kw-clinique\">vertiges</span> / troubles équilibre / <span class=\"kw-clinique\">paralysie faciale</span></strong></td>\n            <td><span class=\"kw-imagerie\">IRM systématique</span> — neurinome très probable.</td>\n          </tr>\n          <tr>\n            <td><strong>SP post-traumatique</strong></td>\n            <td><span class=\"kw-imagerie\">TDM des rochers</span> en 1ʳᵉ intention → fracture transversale (atteinte cochlée/labyrinthe). <br><span class=\"kw-imagerie\">IRM</span> en <span class=\"kw-bio\">complément</span> si suspicion de commotion labyrinthique ou <span class=\"kw-clinique\">fistule</span> périlymphatique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Place de la <span class=\"kw-imagerie\">TDM</span> dans la SP</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">Fracture transversale du rocher</span> (atteinte cochlée/labyrinthe).</li>\n        <li><span class=\"kw-imagerie\">Anomalies osseuses de l'oreille interne</span> : déhiscence du canal semi-circulaire supérieur, anomalie de Mondini chez l'enfant.</li>\n        <li><span class=\"kw-def\">Bilan pré-opératoire</span> <strong>avant implant cochléaire</strong> (anatomie cochléaire, canal de Falloppe).</li>\n      </ul>\n\n      <h4>3 · PEAP comme orientation préalable</h4>\n      <p><span class=\"kw-clinique\">Les</span> PEAP donnent une <strong>orientation topographique avant l'<span class=\"kw-imagerie\">IRM</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-bio\">↑ latence I-III</span> = nerf VIII ou partie basse du tronc → <span class=\"kw-imagerie\">IRM</span> injectée.</li>\n        <li><span class=\"kw-bio\">↑ latence III-V</span> = anomalie plus haute dans le tronc cérébral → <span class=\"kw-imagerie\">IRM</span> cérébrale.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau.</strong> Toute SP <span class=\"kw-alerte\">unilatérale d'apparition récente</span>, même partielle, doit faire suspecter un <strong>neurinome de l'acoustique</strong> — <span class=\"kw-imagerie\">IRM</span> injectée systématique. Pas d'<span class=\"kw-imagerie\">IRM</span> = pas de diagnostic.\n      </div>","frequence":0},{"id":"89-13","rang":"B","rubrique":"Examens complémentaires","titre":"Indication des examens d’imagerie devant une SP chez l’enfant","contenu":"<p>La SP de l'enfant est le plus souvent <span class=\"kw-etio\">d'origine génétique</span> (majorité des surdités handicapantes pédiatriques) ou <span class=\"kw-etio\">périnatale</span> (prématurité, hypoxie, ototoxiques, <span class=\"kw-clinique\">ictère</span>, infection materno-fœtale). Le bilan d'imagerie est <strong>systématique</strong> devant une SP confirmée.</p>\n\n      <h4>1 · Bilan d'imagerie systématique</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication / question</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">TDM</span> des rochers haute résolution</strong></td>\n            <td><span class=\"kw-imagerie\">Recherche de malformations osseuses</span> : anomalie de <strong>Mondini</strong> (cochlée incomplète avec partition incomplète), dilatation de l'aqueduc vestibulaire, hypoplasie cochléaire, déhiscence du canal semi-circulaire supérieur. <br>Bilan <strong>pré-opératoire avant implant cochléaire</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> cérébrale + APC + oreille interne</strong></td>\n            <td><span class=\"kw-imagerie\">Recherche d'aplasie nerveuse</span> : <span class=\"kw-alerte\">agénésie du nerf cochléaire = CI à l'implant cochléaire</span>. <br>Atteinte des voies auditives centrales. <br><span class=\"kw-clinique\">Lésion</span> vasculaire ou <span class=\"kw-etio\">tumorale</span> (rare).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> transfontanellaire</strong> (nourrisson)</td>\n            <td>Recherche d'une <span class=\"kw-imagerie\">lésion intracrânienne associée</span> si suspicion de surdité syndromique.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Bilan complémentaire associé (toujours multimodal)</h4>\n      <ul>\n        <li><strong>Bilan <span class=\"kw-etio\">génétique</span></strong> — panel surdité (mutation <span class=\"kw-etio\">connexine 26 GJB2</span> = la plus fréquente).</li>\n        <li><strong><span class=\"kw-bio\">Sérologies</span> materno-fœtales</strong> — <span class=\"kw-alerte\">CMV ++</span>, rubéole, toxoplasmose, <span class=\"kw-clinique\">syphilis</span> (<span class=\"kw-bio\">PCR</span> salivaire ou Guthrie avant <span class=\"kw-chiffre\">J21</span> pour <span class=\"kw-etio\">CMV</span>).</li>\n        <li><strong>Examen ophtalmologique systématique</strong> — syndrome de <span class=\"kw-etio\">Usher</span> (SP + rétinopathie p<span class=\"kw-chiffre\">igm</span>entaire).</li>\n        <li><strong><span class=\"kw-bio\">ECG</span></strong> — syndrome de <span class=\"kw-etio\">Jervell-Lange-Nielsen</span> (SP + QT long → <span class=\"kw-alerte\">mort subite</span>).</li>\n        <li><strong>Bilan thyroïdien</strong> — syndrome de <span class=\"kw-etio\">Pendred</span> (SP + goitre).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Objectif de l'imagerie.</strong> <span class=\"kw-imagerie\">Identifier les malformations curables ou implantables</span> + détecter <span class=\"kw-clinique\">les</span> CI à l'implant cochléaire (agénésie du nerf cochléaire). Le résultat oriente la stratégie de réhabilitation auditive (prothèse <span class=\"kw-bio\">vs</span> implant unilatéral <span class=\"kw-bio\">vs</span> implant bilatéral) et le timing (idéalement avant <span class=\"kw-chiffre\">18 mois</span> pour le développement du langage).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":0},{"id":"89-14","rang":"A","rubrique":"Etiologie","titre":"Connaître les étiologies principales des SP","contenu":"<p>Deux axes de <span class=\"kw-def\">classification</span> : <strong>topographique</strong> (endo- <span class=\"kw-bio\">vs</span> rétrocochléaire) et <strong>par latéralité</strong> (uni- <span class=\"kw-bio\">vs</span> bilatérale).</p>\n\n      <h4>1 · <span class=\"kw-def\">Classification</span> topographique</h4>\n      <table >\n        <thead>\n          <tr><th>Endocochléaire</th><th>Rétrocochléaire</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Maladie de Ménière</span> <br><span class=\"kw-etio\">Surdité brutale (SUB)</span> <br><span class=\"kw-etio\">Surdité due au bruit</span> <br><span class=\"kw-etio\">Presbyacousie ⭐</span> <br><span class=\"kw-etio\">Atteinte virale ou toxique</span> <br><span class=\"kw-etio\">Traumatique</span> <br><span class=\"kw-etio\">Surdité génétique</span></td>\n            <td><span class=\"kw-alerte\">Neurinome de l'acoustique (schwannome vestibulaire)</span> <br><span class=\"kw-etio\">Méningiome de l'APC</span> <br>Atteinte du tronc cérébral</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2 · <span class=\"kw-def\">Classification</span> par latéralité</h4>\n      <table >\n        <thead>\n          <tr><th>Unilatérale</th><th>Bilatérale</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Surdité unilatérale brusque (<span class=\"kw-etio\">virale</span>, vasculaire, idiopathique, <strong>neurinome</strong>) <br>Surdité traumatique (<span class=\"kw-clinique\">lésion</span> oreille interne ± fracture rocher) <br>Labyrinthites otogènes ou neurolabyrinthites <br>Maladie de Ménière (initialement unilatérale, peut devenir bilatérale dans <span class=\"kw-chiffre\">10-15 %</span>) <br>Neurinome de l'acoustique</td>\n            <td>Surdité d'origine <span class=\"kw-etio\">génétique</span> <br>Presbyacousie <br>Traumatismes sonores <br>Surdités toxiques <br>Neurolabyrinthites post-<span class=\"kw-def\">méningite</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Presbyacousie ⭐ (étiologie la plus fréquente)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"kw-def\">Processus normal de vieillissement</span> portant sur <span class=\"kw-clinique\">les</span> structures neurosensorielles (≠ maladie) — oreille interne (CCE > CCI) + voies auditives du SNC.</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-chiffre\">1/3 des ≥ 65 ans</span> · <span class=\"kw-chiffre\">40 % des &gt; 75 ans</span> · <span class=\"kw-chiffre\">60 % des &gt; 85 ans</span> · 1ʳᵉ étiologie du sujet âgé.</td></tr>\n          <tr><td><strong>Surdité</strong></td><td>SP progressive, <span class=\"kw-clinique\">bilatérale, symétrique</span>, prédominant dans <span class=\"kw-clinique\">les</span> <strong>aigus</strong>. Début ~<span class=\"kw-chiffre\">25 ans</span>, révélation clinique <span class=\"kw-chiffre\">60-65 ans</span>.</td></tr>\n          <tr><td><strong>Mécanisme</strong></td><td>Dégénérescence des <strong>CCE</strong> (« j'entends mais je ne comprends pas »), des <strong>CCI</strong> (élévation du seuil), puis atteinte des voies centrales.</td></tr>\n          <tr><td><strong>FR de début précoce</strong></td><td><span class=\"kw-etio\">Génétique</span> · insuffisance vasculaire · <span class=\"kw-ttt\">diabète, HTA, dyslipidémie</span> · exposition au bruit · iatrogénie ototoxique.</td></tr>\n          <tr><td><strong>Conséquences</strong></td><td><span class=\"kw-alerte\">FR de démence</span> chez le sujet âgé · <span class=\"kw-def\">isolement</span> · <span class=\"kw-def\">dépression</span> réactionnelle.</td></tr>\n          <tr><td><strong>Audiogramme</strong></td><td>Perte aiguë symétrique, courbes CO + CA superposées.</td></tr>\n          <tr><td><strong>Prise en charge</strong></td><td><span class=\"kw-ttt\">Pas de traitement curatif ❌</span>. Prothèse auditive bilatérale dès <span class=\"kw-chiffre\">perte &gt; 30 dB sur fréquences conversationnelles</span> ou <span class=\"kw-chiffre\">&gt; 30 %</span> en vocale. ± rééducation orthophonique (lecture labiale).</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Surdité unilatérale brusque (SUB)</h4>\n      <ul>\n        <li><strong>Installation</strong> : <span class=\"kw-clinique\">« coup de tonnerre dans un ciel serein »</span>, en quelques secondes/minutes.</li>\n        <li><strong>Présentation</strong> : unilatérale, ± profonde, ± <span class=\"kw-clinique\">sifflements</span>, ± <span class=\"kw-clinique\">vertiges</span>.</li>\n        <li><strong>Étiologies</strong> : <span class=\"kw-etio\">virale</span>, <span class=\"kw-etio\">vasculaire</span>, <span class=\"kw-alerte\">10 % révélatrices d'un neurinome</span> (PEA + <span class=\"kw-imagerie\">IRM</span> systématiques) · idiopathique le plus souvent.</li>\n        <li><strong>Traitement</strong> : <span class=\"kw-ttt\">URGENCE médicale</span> — <span class=\"kw-ttt\">corticothérapie</span> générale et/ou intratympanique 6-8 j (efficacité <strong>nulle au-delà du 8-10ᵉ jour</strong>) ± vasodilatateurs, <span class=\"kw-ttt\">oxygénothérapie</span> hyperbare, hémodilution.</li>\n        <li><strong><span class=\"kw-def\">Pronostic</span></strong> : réservé — <span class=\"kw-chiffre\">50-75 % ne récupèrent pas</span>.</li>\n      </ul>\n\n      <h4>5 · Surdité traumatique</h4>\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Fracture du rocher transversale</strong></td><td>Atteinte de l'oreille interne (cochlée) → <span class=\"kw-alerte\">SP unilatérale</span>, totale ou partielle, ± évolutive, + acouphènes + <span class=\"kw-clinique\">vertiges</span>.</td></tr>\n          <tr><td><strong>Commotion labyrinthique sans fracture</strong></td><td>Propagation de l'onde de <span class=\"kw-alerte\">choc</span> → SP <span class=\"kw-clinique\">souvent régressive</span> (totalement ou partiellement).</td></tr>\n          <tr><td><strong>Syndrome post-traumatique</strong></td><td>Surdité résiduelle · <span class=\"kw-def\">incidence</span> <span class=\"kw-clinique\">médico-légale</span> fréquente.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Fistule</span> périlymphatique</strong></td><td>À évoquer devant toute SP évolutive ou fluctuante post-traumatique.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>6 · Labyrinthites infectieuses</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Hématogène</strong></td><td><span class=\"kw-etio\">Oreillons</span> (SP unilatérale), <span class=\"kw-etio\">zona auriculaire</span> (atteinte VIII), virus neurotropes, <span class=\"kw-clinique\">syphilis</span> (exceptionnelle).</td></tr>\n          <tr><td><strong>Neurolabyrinthites post-<span class=\"kw-def\">méningite</span></strong></td><td>Surtout <span class=\"kw-etio\">pneumocoque</span> et <span class=\"kw-etio\">méningocoque</span> → <span class=\"kw-alerte\">SP bilatérale totale irréversible et incurable</span>. <br><span class=\"kw-ttt\">URGENCE : implant cochléaire bilatéral</span> en <span class=\"kw-alerte\">urgence</span> (risque d'ossification cochléaire secondaire).</td></tr>\n          <tr><td><strong>Labyrinthite otogène</strong></td><td>Propagation d'une infection de l'oreille moyenne (OMA, cholestéatome) par <span class=\"kw-clinique\">fistule</span> des fenêtres ou du canal semi-circulaire externe. <br><span class=\"kw-clinique\">Vertige</span> + nystagmus + SP + <span class=\"kw-clinique\">signe de la fistule</span> (hyperpression/<span class=\"kw-def\">dépression</span> d'<span class=\"kw-def\">air</span> dans le conduit → <span class=\"kw-clinique\">vertige</span> et nystagmus, recherché à l'<strong>otoscope pneumatique</strong>). <br><span class=\"kw-imagerie\">TDM de l'oreille</span> pour visualiser la fistule. <br><span class=\"kw-ttt\">ATB + corticothérapie ± chirurgie en urgence</span> (cholestéatome).</td></tr>\n        </tbody>\n      </table>\n\n      <h4>7 · Surdité d'origine <span class=\"kw-etio\">génétique</span></h4>\n      <ul>\n        <li><strong>Transmission</strong> : <span class=\"kw-etio\">autosomique dominante</span> souvent.</li>\n        <li><strong><span class=\"kw-def\">Terrain</span></strong> : <span class=\"kw-clinique\">adulte jeune</span> (maladie évolutive du jeune).</li>\n        <li><strong>Surdité</strong> : cochléaire, bilatérale, installation progressive, aggravation au fil du temps · ± acouphènes bilatéraux.</li>\n        <li><strong>Retentissement</strong> : <span class=\"kw-alerte\">handicap fonctionnel dramatique chez le sujet en pleine activité professionnelle</span>.</li>\n        <li><strong>Prise en charge</strong> : <span class=\"kw-ttt\">prothèse acoustique amplificatrice</span> puis <span class=\"kw-ttt\">implant cochléaire</span> si surdité profonde bilatérale.</li>\n      </ul>\n\n      <h4>8 · Traumatisme sonore</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Chronique professionnel</strong></td>\n            <td>Milieu industriel bruyant (forgerons, chaudronniers…). <br>Zone d'alarme : <span class=\"kw-chiffre\">85 dB pendant 8 h/j</span>. <br>Sons <span class=\"kw-clinique\">les</span> plus nocifs : <span class=\"kw-clinique\">sons impulsifs, spectres aigus</span>. <br>1ᵉʳ signe = <span class=\"kw-imagerie\">scotome auditif bilatéral à 4 000 Hz</span> (encoche à 4 000 Hz). <br><span class=\"kw-def\">Stade</span> irréversible : extension aux fréquences conversationnelles. <span class=\"kw-clinique\">Pas d'évolution après éviction du bruit</span>. <br><span class=\"kw-ttt\">Pas de traitement ❌</span> — prévention obl<span class=\"kw-chiffre\">iga</span>toire (protection, audiogrammes médecine du travail, seuil réglementaire <span class=\"kw-chiffre\">80 dB depuis 2006</span>). <br>Reconnaissance en <strong>Maladie professionnelle tableau 42</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Aigu accidentel (bruit soudain et violent)</strong></td>\n            <td>Bilatéral, prédominance 4 000 Hz, ± <span class=\"kw-clinique\">sifflements</span> ± <span class=\"kw-clinique\">vertiges</span>. <br><span class=\"kw-ttt\">Traitement d'urgence comme une SUB</span> (<span class=\"kw-ttt\">corticoïdes</span>, vasodilatateurs, <span class=\"kw-ttt\">oxygénothérapie</span> hyperbare, hémodilution). <br><span class=\"kw-def\">Pronostic</span> : peut régresser totalement ou partiellement. <br>Reconnaissance en <strong>accident du travail (AT)</strong> si survenue brutale pendant le travail.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/audiogramme-trauma-sonore-encoche-4000hz.png\" alt=\"Audiogramme traumatisme sonore chronique : encoche caractéristique bilatérale à 4 000 Hz.\" loading=\"lazy\">\n        <figcaption>Audiogramme du traumatisme sonore chronique — <strong>encoche caractéristique à 4 000 Hz</strong>, bilatérale (<span class=\"kw-bio\">vs</span> encoche de Carhart à 2 000 Hz dans l'otospongiose). Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <h4>9 · Surdité <span class=\"kw-etio\">toxique</span></h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Caractéristiques</strong></td><td>Bilatérale (drogue par voie générale), perte prédominant sur <span class=\"kw-clinique\">les</span> aigus, <span class=\"kw-alerte\">irréversible et incurable</span>.</td></tr>\n          <tr><td><strong>Médicaments / toxiques ⭐</strong></td><td><span class=\"kw-ttt\">Aminosides</span> (tropisme cochléo-vestibulaire) <br><span class=\"kw-ttt\">Furosémide</span> (potentialise <span class=\"kw-clinique\">les</span> aminosides) <br><span class=\"kw-ttt\">Cisplatine, moutarde azotée</span> <br><span class=\"kw-ttt\">Quinine</span> et dérivés <br><span class=\"kw-ttt\">Rétinoïdes</span> <br>Produits industriels : <span class=\"kw-ttt\">CO, mercure, plomb</span>.</td></tr>\n          <tr><td><strong>Contexte de survenue</strong></td><td>Surdosage · répétition des traitements · <span class=\"kw-alerte\">insuffisance rénale</span> · prédisposition <span class=\"kw-etio\">génétique</span> (ADN mitochondrial) pour <span class=\"kw-clinique\">les</span> aminosides.</td></tr>\n          <tr><td><strong>Prévention</strong></td><td>Indications strictes · <span class=\"kw-def\">surveillance</span> fonction rénale · audiogramme systématique chez sujets à risque · adaptation des doses (taux plasmatiques) · <span class=\"kw-ci\">CI des gouttes auriculaires aminosides si perforation tympanique</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/89/memo-surdite-toxique-medicaments.png\" alt=\"Mémo des principaux médicaments et toxiques ototoxiques : aminosides, furosémide, cisplatine, quinine, rétinoïdes, CO, mercure, plomb.\" loading=\"lazy\">\n        <figcaption>Mémo des principaux médicaments et toxiques ototoxiques. Source : fiche source EDN item 89.</figcaption>\n      </figure>\n\n      <h4>10 · Maladie de Ménière (à distinguer)</h4>\n      <ul>\n        <li>SP <strong>endocochléaire</strong> + <span class=\"kw-clinique\">vertiges rotatoires</span> + <span class=\"kw-clinique\">acouphènes</span> + <span class=\"kw-clinique\">plénitude auriculaire</span>.</li>\n        <li>Perte typiquement sur <span class=\"kw-clinique\">les</span> <strong>graves</strong> ou toutes fréquences (exception SP — la plupart prédominent sur les aigus).</li>\n        <li><span class=\"kw-clinique\">Évolution</span> par crises récidivantes — à différencier du neurinome (<span class=\"kw-clinique\">vertige</span> progressif ± troubles équilibre, surdité progressive).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Urgences à connaître.</strong> Toute SP <span class=\"kw-alerte\">unilatérale</span> = <span class=\"kw-imagerie\">IRM</span> injectée systématique (élimination neurinome). Toute SP <span class=\"kw-alerte\">brusque</span> = <span class=\"kw-alerte\">urgence</span> médicale, <span class=\"kw-ttt\">corticothérapie</span> dans <span class=\"kw-clinique\">les</span> 8-10 premiers jours. Toute SP <span class=\"kw-alerte\">bilatérale totale post-méningite</span> = implant cochléaire en urgence.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 103 — <span class=\"kw-clinique\">Vertige</span> · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":1},{"id":"89-15","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les particularités des SP de l’enfant","contenu":"<p>La SP de l'enfant a un <strong>impact majeur sur le développement du langage et la scolarité</strong>. La <span class=\"kw-alerte\">détection précoce avant 6 mois</span> conditionne le <span class=\"kw-def\">pronostic</span> fonctionnel.</p>\n\n      <h4>1 · <span class=\"kw-def\">Épidémiologie</span></h4>\n      <ul>\n        <li><span class=\"kw-chiffre\">~1 / 1 000 naissances</span> = surdité bilatérale néonatale.</li>\n        <li><span class=\"kw-etio\">Origine génétique</span> = <strong>majorité des surdités handicapantes pédiatriques</strong> (autosomique dominante, autosomique récessive — mutation <span class=\"kw-etio\">connexine 26 GJB2</span> la plus fréquente).</li>\n      </ul>\n\n      <h4>2 · Étiologies principales</h4>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Génétiques (majorité)</strong></td>\n            <td>Formes <span class=\"kw-etio\">isolées</span> (DFNA, DFNB) ou <span class=\"kw-etio\">syndromiques</span> : <br>· <span class=\"kw-etio\">Usher</span> = SP + rétinopathie p<span class=\"kw-chiffre\">igm</span>entaire <br>· <span class=\"kw-etio\">Pendred</span> = SP + goitre <br>· <span class=\"kw-etio\">Waardenburg</span> = SP + dyschromie iris/peau/cheveux <br>· <span class=\"kw-alerte\">Jervell-Lange-Nielsen</span> = SP + QT long → <strong><span class=\"kw-alerte\">mort subite</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Périnatales</strong></td>\n            <td>Prématurité, hypoxie néonatale, ototoxiques (aminosides), <span class=\"kw-alerte\">ictère nucléaire</span>, infections materno-fœtales (<span class=\"kw-alerte\">CMV ++</span>, rubéole, toxoplasmose, <span class=\"kw-clinique\">syphilis</span>).</td>\n          </tr>\n          <tr>\n            <td><strong>Acquises</strong></td>\n            <td><span class=\"kw-etio\">OSM</span> = 1ʳᵉ cause de ST de l'enfant (pas SP). <br><span class=\"kw-alerte\">Méningites bactériennes</span> (<span class=\"kw-etio\">pneumocoque</span>, <span class=\"kw-ttt\">méningocoque</span>) → SP bilatérale totale irréversible. <br>Traumatisme sonore. <br>Traumatisme par coton-t<span class=\"kw-chiffre\">ige</span>. <br>Ototoxiques.</td>\n          </tr>\n          <tr>\n            <td><strong>Idiopathiques</strong></td>\n            <td>Diagnostic d'élimination après bilan complet négatif.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>3 · <span class=\"kw-def\">Dépistage</span> néonatal universel</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\">PEAA (PEA automatisés) + OEA</span> systématiques à la maternité depuis <strong>2012 en France</strong> (arrêté du 23/04/2012).</li>\n        <li>Obl<span class=\"kw-chiffre\">iga</span>toire <strong>avant la sortie de maternité</strong>.</li>\n        <li>Répété à<span class=\"kw-chiffre\"> 3 mois</span> si anormal.</li>\n        <li>Diagnostic confirmé <span class=\"kw-clinique\">avant 6 mois</span>.</li>\n      </ul>\n\n      <h4>4 · Conséquences cliniques d'une SP non détectée</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Déficit de développement du langage oral</span> chez l'enfant.</li>\n        <li><span class=\"kw-alerte\">Difficultés dans les apprentissages scolaires</span> chez l'élève.</li>\n        <li>Adulte : difficulté en activité professionnelle (nécessité d'adaptation de poste, perte d'emploi).</li>\n        <li>Sujet âgé : risque de <span class=\"kw-alerte\">dépression</span> et/ou de <span class=\"kw-alerte\">troubles cognitifs</span> secondaires à l'<span class=\"kw-def\">isolement</span> sensoriel.</li>\n      </ul>\n\n      <h4>5 · Bilan diagnostique pédiatrique (multimodal)</h4>\n      <ul>\n        <li><strong>Audiométrie comportementale</strong> selon l'âge.</li>\n        <li><span class=\"kw-imagerie\">PEA</span> en sommeil naturel ou sous anesthésie.</li>\n        <li><span class=\"kw-imagerie\">OEA</span>.</li>\n        <li><span class=\"kw-imagerie\">TDM des rochers</span> + <span class=\"kw-imagerie\">IRM cérébrale + APC + oreille interne</span> (cf <em>obj-12</em>).</li>\n        <li><strong>Bilan <span class=\"kw-etio\">génétique</span></strong> (panel surdité — GJB2 d'abord).</li>\n        <li><span class=\"kw-bio\">Sérologies materno-fœtales</span> — gold standard <strong><span class=\"kw-etio\">CMV</span> sur Guthrie ou <span class=\"kw-bio\">PCR</span> salivaire avant <span class=\"kw-chiffre\">J21</span></strong>.</li>\n        <li>Examen ophtalmologique systématique (Usher).</li>\n        <li><span class=\"kw-bio\">ECG</span> (QT long Jervell-Lange-Nielsen).</li>\n        <li>Bilan thyroïdien (Pendred).</li>\n      </ul>\n\n      <h4>6 · Prise en charge</h4>\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Réhabilitation auditive précoce</strong></td>\n            <td><span class=\"kw-ttt\">Prothèse auditive amplificatrice</span> dès le diagnostic confirmé (<span class=\"kw-chiffre\">3-6 mois</span>). <br><span class=\"kw-ttt\">Implant cochléaire bilatéral</span> si surdité profonde ou totale bilatérale (<span class=\"kw-clinique\">idéalement avant 18 mois</span> pour développement du langage).</td>\n          </tr>\n          <tr>\n            <td><strong>Orthophonie</strong></td>\n            <td>Précoce. Apprentissage de la <strong>lecture labiale</strong>, éducation auditive, suppléances mentales. Résultats meilleurs si rééducation précoce + bon entourage familial.</td>\n          </tr>\n          <tr>\n            <td><strong>MDPH</strong></td>\n            <td><span class=\"kw-ttt\">Reconnaissance handicap</span>. Demande des parents avec certificat médical + audiogramme datant de <span class=\"kw-chiffre\">&lt; 1 an</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Information sur la <strong>consanguinité</strong>. <span class=\"kw-def\">Suivi</span> rapproché si ATCD familial de surdité. Prévention prématurité, <span class=\"kw-etio\">alcoolisme</span> fœtal. Limitation des aminosides en néonat. Choix de chimiothérapies moins ototoxiques (carboplatine &lt; cisplatine). Prévention coton-t<span class=\"kw-chiffre\">ige</span> + traumatismes sonores (oreilles très sensibles aux aigus).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ <span class=\"kw-alerte\">Urgence</span> pédiatrique.</strong> Toute suspicion de SP chez l'enfant impose un <span class=\"kw-alerte\">bilan multimodal urgent</span> (audio + imagerie + <span class=\"kw-etio\">génétique</span> + <span class=\"kw-bio\">sérologies</span> + ophtalmo + <span class=\"kw-bio\">ECG</span>) — <span class=\"kw-clinique\">les</span> conséquences sur le langage et la scolarité sont <strong>définitives</strong> si la réhabilitation n'est pas initiée précocement (avant <span class=\"kw-chiffre\">18 mois</span> pour l'implant cochléaire).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> :</strong> la <span class=\"kw-alerte\">surdité de perception brutale unilatérale</span> (« <span class=\"kw-alerte\">coup de tonnerre dans un ciel serein</span> », en <span class=\"kw-chiffre\">secondes à minutes</span>) est une <span class=\"kw-alerte\">urgence médicale</span>.<br><strong>Fenêtre :</strong> traiter dès <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">1ères heures</span> à <span class=\"kw-chiffre\">premiers jours</span> ; efficacité <span class=\"kw-chiffre\">nulle après le 8-10e jour</span>.<br><strong>1er geste :</strong> avis ORL en urgence + <span class=\"kw-ttt\">corticothérapie</span> générale et/ou locale transtympanique.<br><strong>À éliminer :</strong> <span class=\"kw-chiffre\">~10%</span> des surdités brusques révèlent un <span class=\"kw-etio\">neurinome de l'acoustique</span> → <span class=\"kw-imagerie\">IRM</span> / <span class=\"kw-bio\">PEA</span> systématique.</p>","hospit":"<p><strong>Avis ORL urgent :</strong> toute <span class=\"kw-alerte\">surdité brutale</span>, post-traumatique ou associée à des <span class=\"kw-clinique\">vertiges</span>.<br><strong>Ambulatoire :</strong> surdité chronique stable → réhabilitation par <span class=\"kw-ttt\">prothèse auditive</span> (audioprothésiste).<br><strong>Filière chirurgicale :</strong> <span class=\"kw-def\">surdité de transmission</span> souvent curable (<span class=\"kw-etio\">otospongiose</span> → <span class=\"kw-ttt\">stapédotomie</span>) ; <span class=\"kw-ttt\">implant cochléaire</span> si <span class=\"kw-def\">surdité de perception</span> profonde bilatérale.<br><strong>Médico-social :</strong> dossier MDPH pour le handicap auditif.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Surdité brutale unilatérale</span> (« <span class=\"kw-alerte\">coup de tonnerre dans un ciel serein</span> ») = <span class=\"kw-alerte\">urgence</span> à traiter sans délai</li><li><span class=\"kw-clinique\">Vertiges</span>, <span class=\"kw-clinique\">troubles de l'équilibre</span> ou <span class=\"kw-clinique\">nystagmus</span> associés (atteinte labyrinthique ou rétrocochléaire)</li><li>Surdité de perception <span class=\"kw-clinique\">unilatérale</span> ou asymétrique inexpliquée → éliminer un <span class=\"kw-etio\">neurinome de l'acoustique</span> (<span class=\"kw-chiffre\">~10%</span> des surdités brusques)</li><li>Surdité de perception après <span class=\"kw-etio\">traumatisme sonore aigu</span> ou <span class=\"kw-etio\">barotraumatisme de l'oreille interne</span> → CAT d'<span class=\"kw-alerte\">urgence</span> identique à la surdité brusque</li><li>Surdité + <span class=\"kw-clinique\">vertige</span> dans un contexte d'<span class=\"kw-etio\">OMA</span> ou de <span class=\"kw-etio\">cholestéatome</span> → suspicion de <span class=\"kw-etio\">labyrinthite</span>, <span class=\"kw-alerte\">urgence</span> chirurgicale</li><li>Surdité totale bilatérale post-<span class=\"kw-etio\">méningite</span> (neurolabyrinthite) → <span class=\"kw-ttt\">implant cochléaire</span> en <span class=\"kw-alerte\">urgence</span> (risque d'<span class=\"kw-alerte\">ossification cochléaire</span>)</li></ul>","principes":"<p>PEC guidée par le type de surdité (<span class=\"kw-def\">transmission</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">perception</span>) et le caractère aigu ou chronique.</p><p><strong>Démarche initiale (tout patient)</strong></p><p>Imagerie ciblée selon le type : <span class=\"kw-imagerie\">TDM des rochers</span> (transmission) ou <span class=\"kw-imagerie\">IRM</span> (perception)</p><ul><li>1re intention : <span class=\"kw-clinique\">acoumétrie</span> au diapason (<span class=\"kw-clinique\">Weber</span>, <span class=\"kw-clinique\">Rinne</span>) + <span class=\"kw-clinique\">otoscopie</span></li><li>Confirmation : <span class=\"kw-bio\">audiométrie tonale et vocale</span> ± <span class=\"kw-bio\">impédancemétrie</span> (tympanométrie, réflexe stapédien)</li><li><span class=\"kw-bio\">PEA</span> / <span class=\"kw-bio\">OEA</span> : audiométrie objective de l'enfant, du nouveau-né ou du sujet non coopérant</li></ul><p><strong>Surdité de transmission</strong></p><p>ST souvent chirurgicalement curable et facilement appareillable par prothèse</p><ul><li><span class=\"kw-def\">ST</span> = atteinte oreille externe/moyenne, <span class=\"kw-clinique\">Rinne négatif</span>, jamais totale (≤ <span class=\"kw-chiffre\">60 dB</span>)</li><li>Cause locale (<span class=\"kw-etio\">bouchon de cérumen</span>, <span class=\"kw-etio\">OMA</span>, <span class=\"kw-etio\">otite séromuqueuse</span> = 1re cause enfant) → <span class=\"kw-ttt\">traitement étiologique</span> (extraction, <span class=\"kw-ttt\">aérateur transtympanique</span>...)</li><li>Tympan normal → <span class=\"kw-imagerie\">TDM des rochers</span> ; <span class=\"kw-etio\">otospongiose</span> (1re cause adulte) → <span class=\"kw-ttt\">stapédotomie</span> (<span class=\"kw-chiffre\">95%</span> de bons résultats)</li></ul><p><strong>Surdité de perception</strong></p><p>Réhabilitation par <span class=\"kw-ttt\">prothèse auditive</span> ; <span class=\"kw-ttt\">implant cochléaire</span> si surdité profonde/totale bilatérale</p><ul><li><span class=\"kw-def\">SP</span> = atteinte cochléaire (endocochléaire) ou rétrocochléaire, <span class=\"kw-clinique\">Rinne positif</span>, généralement irréversible</li><li>Unilatérale/asymétrique → <span class=\"kw-imagerie\">IRM des angles ponto-cérébelleux injectée</span> pour éliminer un <span class=\"kw-etio\">neurinome</span></li><li>Étiologies : <span class=\"kw-etio\">presbyacousie</span>, <span class=\"kw-etio\">traumatisme sonore</span>, <span class=\"kw-etio\">surdité toxique</span>, <span class=\"kw-etio\">surdité génétique</span>, <span class=\"kw-etio\">maladie de Ménière</span></li></ul><p><strong>Surdité brutale / aiguë (<span class=\"kw-alerte\">urgence</span>)</strong></p><p>Bilan : <span class=\"kw-imagerie\">IRM</span> systématique pour éliminer un <span class=\"kw-etio\">neurinome de l'acoustique</span></p><ul><li><span class=\"kw-ttt\">Corticothérapie</span> générale et/ou injection transtympanique pendant <span class=\"kw-chiffre\">6-8 jours</span></li><li>± <span class=\"kw-ttt\">vasodilatateurs</span>, <span class=\"kw-ttt\">oxygénothérapie hyperbare</span>, <span class=\"kw-ttt\">hémodilution</span></li><li>Délai : débuter dès <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">1ères heures</span> ; inefficace après le <span class=\"kw-chiffre\">8-10e jour</span></li></ul><p><strong>Réhabilitation auditive</strong></p><ul><li>Indication : perte > <span class=\"kw-chiffre\">30 dB</span> en tonale ou seuil d'intelligibilité > <span class=\"kw-chiffre\">30 dB</span> en vocale</li><li>Réhabilitation précoce par <span class=\"kw-ttt\">prothèse auditive</span> (essais obl<span class=\"kw-chiffre\">iga</span>toires, prise en charge <span class=\"kw-chiffre\">100%</span> Santé)</li><li><span class=\"kw-ttt\">Implant cochléaire</span> si bénéfice prothétique insuffisant / surdité profonde bilatérale</li><li>± <span class=\"kw-ttt\">rééducation orthophonique</span> (lecture labiale) si surdité sévère à profonde</li></ul>","suivi":"<p><strong>Audiométrie de contrôle :</strong> <span class=\"kw-def\">suivi</span> de l'<span class=\"kw-clinique\">évolution</span> et de l'efficacité de la réhabilitation.<br><strong>Surdité <span class=\"kw-etio\">toxique</span> :</strong> <span class=\"kw-def\">surveillance</span> de la <span class=\"kw-bio\">fonction rénale</span> + <span class=\"kw-bio\">audiogramme</span> systématique sous <span class=\"kw-ttt\">aminosides</span> ; <span class=\"kw-ci\">contre-indication des gouttes auriculaires aux aminosides si perforation tympanique</span>.<br><strong>Surdité professionnelle :</strong> <span class=\"kw-bio\">audiogrammes</span> de la médecine du travail (seuil de nuisance <span class=\"kw-chiffre\">80 dB</span>) ; déclaration en maladie professionnelle (tableau 42).<br><strong>Handicap :</strong> dossier MDPH avec <span class=\"kw-bio\">audiogramme</span> datant de < <span class=\"kw-chiffre\"><span class=\"kw-chiffre\">1 an</span></span>.</p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/external-auditory-canal-atresia","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/otospongiosis-1","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Surdité (baisse d'audition) confirmée — 1er geste : acoumétrie (Weber / Rinne) + otoscopie","detail":"<h4>CAT — Démarche diagnostique devant une surdité — De l'acoumétrie à l'orientation thérapeutique</h4>","branches":[{"to":"q-brutal","label":"Caractériser l'installation","color":"blue"}]},{"id":"q-brutal","kind":"decision","label":"Installation brutale unilatérale ? — « Coup de tonnerre dans un ciel serein », en secondes à minutes","branches":[{"to":"t-urgence","label":"Oui — coup de tonnerre","color":"red"},{"to":"q-acoumetrie","label":"Non / progressive","color":"blue"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence ORL — surdité brusque — Avis ORL en urgence","color":"red","detail":"<h4>Délai</h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> à débuter dès <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">1ères heures</span></li><li>Efficacité <span class=\"kw-chiffre\">nulle après le 8-10e jour</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM</span> / <span class=\"kw-bio\">PEA</span> : éliminer un <span class=\"kw-etio\">neurinome de l'acoustique</span> (<span class=\"kw-chiffre\">~10%</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticothérapie</span> générale et/ou transtympanique <span class=\"kw-chiffre\">6-8 j</span></li><li>± <span class=\"kw-ttt\">vasodilatateurs</span>, <span class=\"kw-ttt\">oxygénothérapie hyperbare</span>, <span class=\"kw-ttt\">hémodilution</span></li></ul><h4>Conduite</h4><ul><li>Même CAT pour <span class=\"kw-etio\">traumatisme sonore aigu</span> et <span class=\"kw-etio\">barotraumatisme de l'oreille interne</span></li></ul>"},{"id":"q-acoumetrie","kind":"decision","label":"Rinne acoumétrique négatif (CO > CA) ? — Weber côté sourd = transmission · Weber côté sain = perception","branches":[{"to":"q-tympan","label":"Rinne négatif (transmission)","color":"blue"},{"to":"q-sp","label":"Rinne positif (perception)","color":"blue"}]},{"id":"q-tympan","kind":"decision","label":"Otoscopie : tympan anormal ? — Recherche bouchon, épanchement, perforation, cholestéatome","branches":[{"to":"t-st-locale","label":"Tympan anormal","color":"green"},{"to":"t-st-tdm","label":"Tympan normal","color":"amber"}]},{"id":"t-st-locale","kind":"terminal","label":"Surdité de transmission — cause locale — Tympan pathologique","color":"green","detail":"<h4>Étiologies</h4><ul><li><span class=\"kw-etio\">Bouchon de cérumen</span>, <span class=\"kw-etio\">OMA</span>, <span class=\"kw-etio\">otite séromuqueuse</span> (1re cause enfant)</li><li><span class=\"kw-etio\">Perforation</span>, <span class=\"kw-etio\">cholestéatome</span>, séquelles d'otite</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement étiologique</span> : extraction du bouchon, <span class=\"kw-ttt\">aérateur transtympanique</span>, <span class=\"kw-ttt\">chirurgie</span>...</li><li>Surdité souvent <span class=\"kw-ttt\">curable</span>, appareillage facile</li></ul>"},{"id":"t-st-tdm","kind":"terminal","label":"Surdité de transmission à tympan normal — → TDM des rochers","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM des rochers</span> non injectée, haute résolution, fenêtre osseuse</li><li><span class=\"kw-radio\">Hypodensité / épaississement platinaire</span> (une <span class=\"kw-imagerie\">TDM</span> normale n'élimine pas l'otospongiose)</li></ul><h4>Étiologie</h4><ul><li><span class=\"kw-etio\">Otospongiose</span> = 1re cause chez l'adulte (femme jeune, <span class=\"kw-chiffre\">2F/1H</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Stapédotomie</span> + prothèse stapédienne (<span class=\"kw-chiffre\">95%</span> de bons résultats)</li><li>Alternative : <span class=\"kw-ttt\">prothèse auditive</span></li></ul>"},{"id":"q-sp","kind":"decision","label":"Surdité de perception unilatérale ou asymétrique ? — Recherche d'une atteinte rétrocochléaire","branches":[{"to":"t-sp-irm","label":"Unilatérale / asymétrique","color":"amber"},{"to":"t-sp-bilat","label":"Bilatérale symétrique","color":"amber"}]},{"id":"t-sp-irm","kind":"terminal","label":"SP unilatérale → IRM — Éliminer un neurinome","color":"amber","detail":"<h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM des angles ponto-cérébelleux injectée</span></li><li>Recherche d'un <span class=\"kw-etio\">neurinome de l'acoustique</span> / <span class=\"kw-etio\">méningiome</span></li></ul><h4>Traitement</h4><ul><li>Selon l'étiologie + réhabilitation par <span class=\"kw-ttt\">prothèse auditive</span> si perte > <span class=\"kw-chiffre\">30 dB</span></li></ul>"},{"id":"t-sp-bilat","kind":"terminal","label":"SP bilatérale → réhabilitation — Presbyacousie, bruit, toxique, génétique","color":"amber","detail":"<h4>Étiologie</h4><ul><li><span class=\"kw-etio\">Presbyacousie</span>, <span class=\"kw-etio\">traumatisme sonore</span> (encoche <span class=\"kw-chiffre\">4000 Hz</span>), <span class=\"kw-etio\">surdité toxique</span>, <span class=\"kw-etio\">surdité génétique</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Prothèse auditive</span> bilatérale précoce (perte > <span class=\"kw-chiffre\">30 dB</span>)</li><li><span class=\"kw-ttt\">Implant cochléaire</span> si surdité profonde / totale bilatérale</li><li>± <span class=\"kw-ttt\">rééducation orthophonique</span></li></ul>"}]},"cards":[{"i":"173ea06b7d32","n":89,"o":"89-10","u":"Etiologie","t":"Connaître les étiologies principales des ST","q":"Comment catégorisez-vous les étiologies de surdité de transmission (ST) selon l'aspect otoscopique du tympan ?","a":"<p>On peut distinguer trois grandes catégories d'étiologies de surdité de transmission (ST) :</p><ul><li>Les ST à <strong>tympan normal</strong> (la principale étant l'<strong>otospongiose</strong>).</li><li>Les ST par atteinte <strong>tympanique ou de l'oreille moyenne</strong> (avec une otoscopie anormale), incluant les otites, leurs séquelles, les bouchons de cérumen, et les cholestéatomes.</li><li>Les ST <strong>traumatiques</strong>.</li></ul>"},{"i":"4533f0be0bb3","n":89,"o":"89-10","u":"Etiologie","t":"Connaître les étiologies principales des ST","q":"Quels sont les pièges diagnostiques concernant l'otospongiose ?","a":"<p>Un piège classique est de <strong>confondre l'encoche de Carhart</strong> (à <strong>2 000 Hz</strong>, caractéristique de l'otospongiose) avec l'encoche du <strong>traumatisme sonore</strong> (à <strong>4 000 Hz</strong>).</p><ul><li>L'encoche de Carhart est une surdité de transmission chez l'adulte jeune.</li><li>L'encoche du traumatisme sonore est une surdité de perception bilatérale, souvent d'origine professionnelle.</li></ul><p>De plus, un <strong>TDM des rochers normal</strong> n'élimine pas le diagnostic d'otospongiose.</p>"},{"i":"7d74a0bb0f83","n":89,"o":"89-10","u":"Etiologie","t":"Connaître les étiologies principales des ST","q":"Quelles sont les principales étiologies de surdité de transmission chez l'enfant et l'adulte, hors contexte traumatique ?","a":"<ul><li>Chez l'enfant, la <strong>première cause</strong> de surdité de transmission est l'<strong>otite séreuse muqueuse (OSM)</strong> à tympan fermé. Les otites moyennes aiguës (OMA) peuvent également provoquer une ST transitoire.</li><li>Chez l'adulte jeune, la principale étiologie de surdité de transmission à tympan normal est l'<strong>otospongiose</strong>.</li><li>Les <strong>bouchons de cérumen</strong> sont une cause fréquente et facile à diagnostiquer de ST à tout âge.</li></ul>"},{"i":"8b9c06d38ee5","n":89,"o":"89-10","u":"Etiologie","t":"Connaître les étiologies principales des ST","q":"Quelle est la définition de l'otospongiose et quels sont ses signes audiométriques clés ?","a":"<p>L'otospongiose est une <strong>ostéodystrophie</strong> de la capsule labyrinthique, d'origine multifactorielle (génétique, hormonale, virale), entraînant une <strong>fixation anormale de la platine de l'étrier</strong> dans la fenêtre ovale, provoquant ainsi une surdité de transmission.</p><p>Sur le plan audiométrique, l'otospongiose se manifeste par une <strong>surdité de transmission</strong> (pure initialement, puis mixte) avec une <strong>encoche de Carhart</strong> caractéristique à <strong>2 000 Hz</strong>. Le tympanogramme est normal (type A) et le réflexe stapédien est aboli, avec un effet « on-off » quasi pathognomonique en début d'ankylose stapédo-vestibulaire.</p>"},{"i":"2353bb31ea8c","n":89,"o":"89-11","u":"Diagnostic positif","t":"Connaître les caractéristiques de surdités de perception (SP)","q":"Quels sont les résultats attendus de l'acoumétrie et de l'audiométrie tonale dans une surdité de perception (SP) ?","a":"<ul><li><strong>Acoumétrie</strong> : Le signe de Weber est <strong>latéralisé vers l'oreille saine</strong> et le Rinne acoumétrique est <strong>positif</strong>.</li><li><strong>Audiométrie tonale</strong> : Les courbes de <strong>conduction osseuse</strong> (CO) et de <strong>conduction aérienne</strong> (CA) sont <strong>superposées et abaissées</strong> (perte > 20 dB), avec une perte prédominant sur les fréquences aiguës. Une exception est la maladie de Ménière, où la SP peut prédominer sur toutes les fréquences ou sur les graves.</li></ul>"},{"i":"559a8769a554","n":89,"o":"89-11","u":"Diagnostic positif","t":"Connaître les caractéristiques de surdités de perception (SP)","q":"Quel est le principe du recrutement et son utilité pour distinguer une atteinte endocochléaire d'une atteinte rétrocochléaire dans les surdités de perception (SP) ?","a":"<p>Le <strong>recrutement</strong> est la perception douloureuse des sons forts. Il est <strong>présent</strong> en cas de surdité de perception <strong>endocochléaire</strong> (atteinte des cellules sensorielles résiduelles récupérables), ce qui entraîne une forte amélioration du score audiométrique vocal avec l'augmentation du volume (> 70%). À l'inverse, il est <strong>absent</strong> en cas de surdité de perception <strong>rétrocochléaire</strong> (atteinte de la transmission nerveuse), résultant en peu ou pas d'amélioration du score vocal, avec un possible <strong>roll-over</strong>.</p>"},{"i":"620385388a63","n":89,"o":"89-11","u":"Diagnostic positif","t":"Connaître les caractéristiques de surdités de perception (SP)","q":"Quelle investigation est impérative face à une surdité de perception (SP) unilatérale ou bilatérale asymétrique ?","a":"<p>Toute surdité de perception unilatérale ou bilatérale asymétrique impose la réalisation d'une <strong>IRM cérébrale avec injection de produit de contraste</strong> pour rechercher un <strong>neurinome de l'acoustique</strong>. Il ne faut pas conclure à un diagnostic « idiopathique » avant d'avoir réalisé cette IRM.</p>"},{"i":"660edf718fde","n":89,"o":"89-11","u":"Diagnostic positif","t":"Connaître les caractéristiques de surdités de perception (SP)","q":"Comment la latéralité et l'intensité d'une surdité de perception (SP) peuvent-elles se présenter ?","a":"<p>Une surdité de perception peut être unilatérale ou bilatérale. Son intensité maximale est variable, pouvant aller jusqu'à une <strong>cophose</strong> (surdité totale).</p>"},{"i":"78ad4ec2faf4","n":89,"o":"89-11","u":"Diagnostic positif","t":"Connaître les caractéristiques de surdités de perception (SP)","q":"Quels sont les signes cliniques associés spécifiques aux surdités de perception (SP) ?","a":"<ul><li><strong>Voix du patient</strong> : Élévation de la voix (crier comme un sourd) si la surdité est bilatérale et sévère.</li><li><strong>Intelligibilité</strong> : Souvent aggravée dans le bruit (signe du « <strong>cocktail party</strong> »).</li><li><strong>Acouphènes</strong> : Généralement de timbre <strong>aigu</strong> (sifflements), mal tolérés, et plus ou moins bien localisés.</li><li><strong>Signes associés potentiels</strong> : Vertiges et troubles de l'équilibre (si atteinte labyrinthique ou nerveuse).</li><li><strong>Distorsions sonores</strong> :<ul><li><strong>Diplacousie</strong> (perception différente de la hauteur d'un son).</li><li><strong>Recrutement</strong> (perception douloureuse des sons forts, surtout en cas d'atteinte endocochléaire).</li><li>Modification du timbre.</li></ul></li></ul>"},{"i":"e66db3e1e454","n":89,"o":"89-11","u":"Diagnostic positif","t":"Connaître les caractéristiques de surdités de perception (SP)","q":"Comment le réflexe stapédien, les PEAP et les OEA aident-ils à localiser l'atteinte dans une surdité de perception (SP) ?","a":"<ul><li><strong>Réflexe stapédien</strong> : Le seuil est <strong>abaissé</strong> en cas d'atteinte endocochléaire (signe de recrutement), et <strong>aboli</strong> en cas d'atteinte rétrocochléaire.</li><li><strong>Potentiels Évoqués Auditifs Précoces (PEAP)</strong> : Ils montrent une diminution du seuil auditif et permettent un diagnostic topographique grâce à l'analyse des latences (augmentation de l'intervalle I-III pour le nerf VIII, augmentation de l'intervalle III-V pour le tronc cérébral).</li><li><strong>Otoémissions Acoustiques (OEA)</strong> : Elles sont <strong>anormales</strong> en cas d'atteinte endocochléaire et <strong>normales</strong> en cas d'atteinte rétrocochléaire.</li></ul>"},{"i":"ed99bddf15b3","n":89,"o":"89-11","u":"Diagnostic positif","t":"Connaître les caractéristiques de surdités de perception (SP)","q":"Comment l'audiométrie vocale et la tympanométrie contribuent-elles au diagnostic des surdités de perception (SP) ?","a":"<ul><li><strong>Audiométrie vocale</strong> : Des distorsions sonores sont possibles (recrutement, diplacousie). Elle permet de différencier une atteinte endocochléaire (score conservé > 70-80%) d'une atteinte rétrocochléaire (score < 60%, avec <strong>roll-over</strong>).</li><li><strong>Tympanométrie</strong> : Elle est généralement <strong>normale</strong>, indiquant que le tympan et la chaîne ossiculaire sont intacts.</li></ul>"},{"i":"0d8a022747cc","n":89,"o":"89-14","u":"Etiologie","t":"Connaître les étiologies principales des SP","q":"Quelles sont les causes des labyrinthites infectieuses et leurs caractéristiques principales ?","a":"<p>Les labyrinthites infectieuses peuvent être :</p><ul><li><strong>Hématogènes</strong> : Oreillons (surdité unilatérale), zona auriculaire, virus neurotropes, syphilis.</li><li><strong>Neurolabyrinthites post-méningite</strong> : Surtout à <strong>pneumocoque et méningocoque</strong>, entraînant une surdité <strong>bilatérale, totale, irréversible et incurable</strong>. L'implantation cochléaire bilatérale en urgence est cruciale.</li><li><strong>Otogènes</strong> : Propagation d'une infection de l'oreille moyenne (OMA, cholestéatome) par fistule des fenêtres. Elles se manifestent par un vertige, un nystagmus, une surdité et un <strong>signe de la fistule</strong>.</li></ul>"},{"i":"26f717d54b45","n":89,"o":"89-14","u":"Etiologie","t":"Connaître les étiologies principales des SP","q":"Quelles sont les étiologies principales de la surdité unilatérale brusque (SUB) ?","a":"<p>Les étiologies de la surdité unilatérale brusque sont principalement :</p><ul><li><strong>Virales</strong></li><li><strong>Vasculaires</strong></li><li><strong>Idiopathiques</strong> (la plus fréquente)</li><li>Révélatrice d'un <strong>neurinome de l'acoustique</strong> (dans 10% des cas, nécessitant PEA et IRM systématiques).</li></ul>"},{"i":"bd12f2f9b2f8","n":89,"o":"89-14","u":"Etiologie","t":"Connaître les étiologies principales des SP","q":"Quels sont les médicaments et toxiques ototoxiques le plus souvent mis en cause dans les surdités toxiques ?","a":"<p>Les principaux médicaments et toxiques ototoxiques sont :</p><ul><li>Les <strong>aminosides</strong> (à tropisme cochléo-vestibulaire).</li><li>Le <strong>furosémide</strong> (potentialise les aminosides).</li><li>Le <strong>cisplatine</strong>, les moutardes azotées.</li><li>La quinine et ses dérivés.</li><li>Les rétinoïdes.</li><li>Les produits industriels comme le CO, le mercure et le plomb.</li></ul>"},{"i":"be7d0bffc0c2","n":89,"o":"89-14","u":"Etiologie","t":"Connaître les étiologies principales des SP","q":"Comment classifie-t-on les presbyacousies en termes cliniques ?","a":"<p>La presbyacousie est une perte auditive <strong>neurosensorielle progressive, bilatérale et symétrique</strong>, touchant préférentiellement les <strong>fréquences aiguës</strong>. Son début est insidieux vers 25 ans, avec une révélation clinique autour de 60-65 ans.</p>"}]};